// 3D model pipeline.
//
// Reads every `.gltf` / `.glb` under `<input>/models/**`, applies
// mesh compression to its geometry (Meshopt by default, Draco
// opt-in), and writes a binary `.glb` equivalent under
// `<output>/models/**`. Per-file animation names are extracted at
// parse time and bubbled up to the type generator, where they
// become `<ModelName>Animations` string-literal unions.
//
// Why Meshopt as the new default (Tier B.2): Meshopt produces
// 20-40% smaller geometry than Draco AND decodes faster on the
// runtime side (no WASM CPU cost; pure-JS decoder). Khronos and
// glTF Sample Models default to Meshopt now. Apps with downstream
// tooling that requires Draco specifically pass
// `compression: 'draco'`; the runtime ModelBank registers both
// decoders so historical Draco-encoded assets continue to load.
//
// Why one IO + one encoder pair, hoisted to pipeline scope:
// `draco3dgltf.createEncoderModule()` boots a WASM module — non-trivial
// cost. Doing it once per pipeline run (instead of per file) keeps the
// pipeline fast even on directories with hundreds of models. The same
// IO instance is reused for every read/write; gltf-transform's IO is
// stateless w.r.t. the documents it produces. `MeshoptEncoder` is
// also booted once (its `ready` Promise resolves once per process).
//
// Why mesh-compression only on geometry: animation curves and
// texture data are orthogonal to mesh codecs. Both Draco and
// Meshopt cover geometry + (optionally) morph targets + animation
// data; neither touches textures. Texture optimization (KTX2 /
// Basis Universal) is handled by a separate transform — see
// `ktx2Transform.ts`.

import { extname, join, posix, relative, sep } from 'node:path';
import { NodeIO } from '@gltf-transform/core';
import {
  EXTMeshoptCompression,
  KHRDracoMeshCompression,
  KHRTextureBasisu,
} from '@gltf-transform/extensions';
import { draco, meshopt } from '@gltf-transform/functions';
import draco3d from 'draco3dgltf';
import fse from 'fs-extra';
import { glob } from 'glob';
import { MeshoptDecoder, MeshoptEncoder } from 'meshoptimizer';
import { pathToIdentifier } from '../utils/identifier.js';
import { dim, info, success, warn } from '../utils/log.js';
import { ktx2Transform } from './ktx2Transform.js';
import { loadBasisu, NO_BASISU_MESSAGE } from '../encoders/basisEncoder.js';

const SUPPORTED_EXTENSIONS = new Set(['.gltf', '.glb']);

/** Sidecar file patterns the model pipeline silently skips
 *  (no warning). These are known-good co-located files written
 *  by sibling pipelines like `@unsupervised/asset-gen` whose sidecars
 *  share the `models/` bucket with the GLBs they describe. */
const KNOWN_SIDECAR_SUFFIXES = ['.prompt.json'];

export interface ModelAsset {
  /** TS-safe identifier — e.g. `enemies_robot`. */
  identifier: string;
  /** Public path under `/models/`, POSIX separators, leading slash —
   *  e.g. `/models/enemies/robot.glb`. */
  path: string;
  /** Animation `getName()` strings as authored in the source GLTF.
   *  Empty / unnamed animations are filtered out upstream. Order is
   *  the GLTF declaration order, which is stable across re-exports
   *  from the same DCC tool. */
  animations: string[];
}

/** Mesh compression codec for the model pipeline.
 *  - `'meshopt'` (default): EXT_meshopt_compression. 20-40% smaller
 *    than Draco; pure-JS decoder on the runtime side.
 *  - `'draco'`: KHR_draco_mesh_compression. Historical default;
 *    requires the Draco WASM decoder CDN at runtime.
 *  - `'none'`: no mesh compression. Useful for debugging or when
 *    downstream tooling needs raw geometry. */
export type MeshCompression = 'meshopt' | 'draco' | 'none';

/** Texture compression codec for the model pipeline.
 *  - `'ktx2'` (default): Basis Universal payload in a KTX2
 *    container. Per-slot encoder selection — UASTC for data
 *    textures (normal / ORM), ETC1S for color (basecolor /
 *    emissive). 5-10× smaller downloads + GPU-native VRAM
 *    compression (~4× VRAM win on top of the download win).
 *  - `'none'`: textures pass through uncompressed (PNG / JPG).
 *    Useful for debugging the encoder pipeline or for models
 *    whose textures are intentionally raw. */
export type TextureCompression = 'ktx2' | 'none';

export interface RunModelPipelineArgs {
  inputDir: string;
  outputDir: string;
  /** Geometry compression codec. Default `'meshopt'`. */
  compression?: MeshCompression;
  /** Texture compression codec. Default `'ktx2'`. */
  textureCompression?: TextureCompression;
}

/**
 * Find, compress, and emit GLB models. `<output>/models/` is wiped
 * before each run so deleted sources don't linger.
 */
export async function runModelPipeline(
  args: RunModelPipelineArgs,
): Promise<ModelAsset[]> {
  const compression: MeshCompression = args.compression ?? 'meshopt';
  const textureCompression: TextureCompression =
    args.textureCompression ?? 'ktx2';
  const modelInputRoot = join(args.inputDir, 'models');
  const modelOutputRoot = join(args.outputDir, 'models');

  if (!(await fse.pathExists(modelInputRoot))) {
    dim('Models: skipped (no models directory under input)');
    return [];
  }

  const allFiles = await glob('**/*', {
    cwd: modelInputRoot,
    nodir: true,
    posix: true,
  });

  const supported: string[] = [];
  for (const file of allFiles) {
    if (SUPPORTED_EXTENSIONS.has(extname(file).toLowerCase())) {
      supported.push(file);
    } else if (KNOWN_SIDECAR_SUFFIXES.some((s) => file.endsWith(s))) {
      // Known sibling-pipeline sidecar (e.g., asset-gen's
      // `.prompt.json`). Silently skipped; the sibling
      // pipeline handles them.
      continue;
    } else {
      warn(`Models: unsupported file type, skipping ${posix.join('models', file)}`);
    }
  }

  if (supported.length === 0) {
    dim('Models: no models to process');
    await fse.emptyDir(modelOutputRoot);
    return [];
  }

  await fse.emptyDir(modelOutputRoot);
  info(
    `Models: processing ${supported.length} model${supported.length === 1 ? '' : 's'}…`,
  );

  // Build the IO once. We register BOTH Draco and Meshopt
  // extensions regardless of the selected output codec so:
  //   1. Input files using EITHER codec parse correctly (apps
  //      can import Blender-exported Meshopt models or older
  //      Draco-encoded glb files).
  //   2. Switching `compression` between runs doesn't churn the
  //      IO setup.
  // Draco's encoder + decoder WASM modules are booted at
  // pipeline scope. Meshopt's encoder + decoder are pure JS
  // (no WASM CDN) but both expose `ready` Promises that must
  // resolve before first use.
  const [encoderModule, decoderModule] = await Promise.all([
    draco3d.createEncoderModule(),
    draco3d.createDecoderModule(),
    MeshoptEncoder.ready,
    MeshoptDecoder.ready,
  ]);
  const io = new NodeIO()
    .registerExtensions([
      KHRDracoMeshCompression,
      EXTMeshoptCompression,
      KHRTextureBasisu,
    ])
    .registerDependencies({
      'draco3d.encoder': encoderModule,
      'draco3d.decoder': decoderModule,
      'meshopt.encoder': MeshoptEncoder,
      'meshopt.decoder': MeshoptDecoder,
    });

  const assets: ModelAsset[] = [];
  let totalAnimations = 0;
  /** One warning per RUN when the optional Basis encoder is absent. */
  let warnedNoBasisu = false;

  for (const relPath of supported) {
    const absInput = join(modelInputRoot, relPath);
    // Output is always `.glb` — binary form is denser than the
    // JSON-and-bin sidecar pair, and the loader code in the
    // renderer doesn't have to special-case two extensions.
    const relGlb = swapExtension(relPath, '.glb');
    const absOutput = join(modelOutputRoot, relGlb);

    try {
      const document = await io.read(absInput);

      // 1. Extract animation names BEFORE the Draco transform —
      //    Draco only touches geometry, but reading first proves
      //    the file is well-formed before we spend WASM cycles
      //    encoding it.
      const animationNames = document
        .getRoot()
        .listAnimations()
        .map((animation) => animation.getName())
        .filter((name) => name.length > 0);

      // 2. Compress geometry. Both `draco()` and `meshopt()`
      //    defer actual encoding until `io.write()` runs.
      if (compression === 'meshopt') {
        await document.transform(
          meshopt({ encoder: MeshoptEncoder, level: 'medium' }),
        );
      } else if (compression === 'draco') {
        await document.transform(draco());
      }
      // `'none'` skips the compression step entirely.

      // 3. Compress textures via KTX2 / Basis Universal. Per-slot
      //    codec selection (UASTC for data textures, ETC1S for
      //    color). Skipped when no textures are present, which is
      //    common for primitives / dev cubes.
      if (textureCompression === 'ktx2' && (await loadBasisu()) !== null) {
        await document.transform(ktx2Transform());
      } else if (textureCompression === 'ktx2' && !warnedNoBasisu) {
        // DEGRADE, don't fail. An uncompressed texture is bigger, not broken —
        // so a missing optional encoder must not take the build down. Warned
        // once per run rather than per model, because the fix is one command
        // and repeating it per file buries every other line of output.
        warn(`Models: ${NO_BASISU_MESSAGE}`);
        warnedNoBasisu = true;
      }

      // 4. Write the compressed GLB.
      await fse.ensureDir(join(absOutput, '..'));
      await io.write(absOutput, document);

      assets.push({
        identifier: pathToIdentifier(relPath),
        // Always emit POSIX separators for cross-OS-stable output.
        path: '/' + posix.join('models', relGlb.split(sep).join(posix.sep)),
        animations: animationNames,
      });
      totalAnimations += animationNames.length;
    } catch (cause) {
      warn(
        `Models: failed to process ${posix.join('models', relPath)} — ${
          cause instanceof Error ? cause.message : String(cause)
        }`,
      );
    }
  }

  // Stable ordering → stable generated TS → minimal VCS diffs.
  assets.sort((a, b) => a.identifier.localeCompare(b.identifier));

  const meshLabel =
    compression === 'none' ? 'no mesh compression' : `${compression} meshes`;
  const textureLabel =
    textureCompression === 'none' ? 'raw textures' : 'ktx2 textures';
  success(
    `Models: processed ${assets.length} model${assets.length === 1 ? '' : 's'} (${meshLabel} + ${textureLabel}) and extracted ${totalAnimations} animation${totalAnimations === 1 ? '' : 's'} → ${relative(process.cwd(), modelOutputRoot)}`,
  );

  return assets;
}

function swapExtension(p: string, newExt: string): string {
  const ext = extname(p);
  return p.slice(0, p.length - ext.length) + newExt;
}
