// Basis Universal encoder wrapper.
//
// Thin wrapper around `@gpu-tex-enc/basis` — Khronos's basisu
// native binary, bundled per-platform via npm. The package ships
// pre-built basisu binaries for darwin-arm64 / darwin-x64 /
// linux-arm64 / linux-x64 / win32-x64, picked at runtime based on
// `process.platform` + `process.arch`. No `brew install`, no
// `apt install ktx-tools` — `pnpm install` resolves everything.
//
// Why a wrapper:
//   1. `@gpu-tex-enc/basis` operates on file paths (PNG path in,
//      KTX2 path out). The gltf-transform `ktx2Transform` works on
//      in-memory texture buffers. The wrapper bridges the two via
//      temp files + cleanup.
//   2. The package's encoder API is loosely typed (`options:
//      string[]`). We expose a strongly typed `{ format,
//      qualityLevel }` interface so the transform layer doesn't
//      poke at CLI flag strings.
//   3. Swapping encoder packages later is a one-file change —
//      `encodeBasisU(bytes, opts) → Promise<Uint8Array>` is the
//      stable interface; the chosen package is an implementation
//      detail.
//
// Output format: KTX2 container with Basis Universal payload.
// Two payload codecs:
//   - UASTC: 4× compression, higher quality. Used for normal /
//     roughness / metalness / ORM textures where banding visibly
//     degrades shading.
//   - ETC1S: 8-16× compression, smaller files. Used for albedo /
//     emissive / decal textures where mild block artifacts hide
//     in the eye's color-perception roll-off.

import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

/** The basisu binary ships as a ~20 MB per-platform package, and a game with
 *  no textures never needs it — so `@gpu-tex-enc/basis` is an OPTIONAL peer
 *  dependency that pnpm does not install. Resolved on first encode and
 *  memoised; `null` means "not installed", which callers treat as
 *  "skip texture compression", never as a build failure. An uncompressed
 *  texture is larger, not broken. */
type BasisuGenerate = (
  input: string,
  format: 'UASTC' | 'ETC1S',
  ktx2: boolean,
  args: string[],
) => string;

let basisuGenerate: BasisuGenerate | null | undefined;

export async function loadBasisu(): Promise<BasisuGenerate | null> {
  if (basisuGenerate !== undefined) return basisuGenerate;
  try {
    const mod = (await import('@gpu-tex-enc/basis')) as { generate?: BasisuGenerate };
    basisuGenerate = mod.generate ?? null;
  } catch {
    basisuGenerate = null;
  }
  return basisuGenerate;
}

/** What to tell an author who wants smaller textures. */
export const NO_BASISU_MESSAGE =
  'texture compression skipped — @gpu-tex-enc/basis is not installed. ' +
  'Run `pnpm add -D @gpu-tex-enc/basis` for KTX2 / Basis Universal textures ' +
  '(5-10x smaller downloads, ~4x less VRAM).';


/** Basis Universal payload codec inside the KTX2 container. */
export type BasisFormat = 'uastc' | 'etc1s';

export interface EncodeBasisOptions {
  /** Payload codec. UASTC for data textures (normal / ORM);
   *  ETC1S for color (albedo / emissive). */
  format: BasisFormat;
  /** Quality level for the chosen codec. Maps to basisu's
   *  `-uastc_level` (0-4) for UASTC and `-q` (1-255) for ETC1S.
   *  Defaults are calibrated for "good quality at acceptable
   *  encode time" — bump for production releases. */
  qualityLevel?: number;
  /** Whether to generate mipmaps inside the KTX2 container.
   *  Enabled by default. Set false for textures that should not
   *  mip (UI / decal sprites where minification is undesired). */
  mipmaps?: boolean;
}

/** Encode a PNG / JPG buffer to a KTX2 container with the chosen
 *  Basis Universal payload codec.
 *
 *  Implementation: writes the input to a temp file, invokes the
 *  basisu binary via `@gpu-tex-enc/basis`'s `generate()`, reads
 *  the resulting `.ktx2` back as a Uint8Array, removes both temp
 *  files. The encoder is process-isolated (subprocess spawn);
 *  parallel calls are safe.
 *
 *  Performance: ~50-200ms per 1024² texture depending on format +
 *  quality level. Pipeline-scope cost is dominated by I/O setup,
 *  not encoder runtime. */
export async function encodeBasisU(
  inputBytes: Uint8Array,
  opts: EncodeBasisOptions,
): Promise<Uint8Array> {
  const tmpRoot = await mkdtemp(join(tmpdir(), 'forge-basis-'));
  // basisu reads from a real file extension to detect input
  // format. Use `.png` — PNG is the lingua-franca for embedded
  // GLB textures. JPG inputs also decode correctly through this
  // path (basisu auto-detects from the file header, not the
  // extension).
  const inPath = join(tmpRoot, 'in.png');
  await writeFile(inPath, inputBytes);

  const generate = await loadBasisu();
  if (generate === null) {
    await rm(tmpRoot, { recursive: true, force: true });
    throw new Error(NO_BASISU_MESSAGE);
  }

  const args = buildBasisuArgs(opts);
  try {
    const outPath = generate(
      inPath,
      opts.format === 'uastc' ? 'UASTC' : 'ETC1S',
      /* ktx2 */ true,
      args,
    );
    const buffer = await readFile(outPath);
    return new Uint8Array(buffer);
  } finally {
    await rm(tmpRoot, { recursive: true, force: true });
  }
}

/** Build the basisu CLI arg list for a given format + quality.
 *
 *  Notes on the chosen knobs:
 *  - `-ktx2_no_zstandard`: skip zstd super-compression on the
 *    final container. The renderer-side `KTX2Loader` supports
 *    zstd, but skipping it keeps the output bytes deterministic
 *    + lets downstream HTTP gzip/brotli handle the final
 *    compression layer (typical CDN behavior).
 *  - `-mipmap`: generate mip levels at encode time. Always
 *    cheaper than runtime mip generation; required for correct
 *    minification on tiled surfaces. */
function buildBasisuArgs(opts: EncodeBasisOptions): string[] {
  const args: string[] = ['-ktx2_no_zstandard'];
  if (opts.mipmaps !== false) {
    args.push('-mipmap');
  }
  if (opts.format === 'uastc') {
    // UASTC quality knob. 4 is the highest static level; the
    // additional `-uastc_rdo_l` rate-distortion-optimization
    // pass squeezes out ~30% more compression at a small
    // quality cost.
    const level = opts.qualityLevel ?? 2;
    args.push('-uastc_level', String(level));
    args.push('-uastc_rdo_l', '0.75');
  } else {
    // ETC1S quality knob. basisu accepts 1-255; the default
    // 128 is the documented "good quality" baseline.
    const quality = opts.qualityLevel ?? 128;
    args.push('-q', String(quality));
  }
  return args;
}
