// Texture-slot classification — picks the right Basis Universal
// encoder format per-texture based on what material slot the
// texture is bound to.
//
// Why this matters: Basis Universal has two payload codecs with
// very different quality / size tradeoffs:
//   - ETC1S: 8-16× compression, mild block artifacts. Hide in
//     color textures (albedo / emissive / decal) where the eye's
//     color-perception roll-off makes the artifacts invisible.
//   - UASTC: 4× compression, near-lossless. Required for data
//     textures (normal / roughness / metalness / ORM /
//     displacement) where banding visibly degrades shading.
//
// Picking the wrong format produces visible failure modes:
//   - Normal map encoded as ETC1S → blocky shading + faceted
//     highlights on every lit surface.
//   - Albedo encoded as UASTC → 2-4× larger download than needed.
//
// The classifier walks every material in the document and asks
// "which slot returns this texture?" The first slot that matches
// wins. Multi-slot textures (same texture used as both
// `baseColor` and `emissive`, rare) pick the most conservative
// format (UASTC) — quality wins over size for ambiguous cases.

import type { Document, Material, Texture } from '@gltf-transform/core';

/** Coarse material-slot category for encoder-format selection. */
export type TextureSlot =
  | 'basecolor'
  | 'emissive'
  | 'normal'
  | 'orm' // occlusion + metallic + roughness (glTF packs these)
  | 'unknown';

/** Default encoder format per slot:
 *  - color slots → ETC1S (smaller)
 *  - data slots → UASTC (lossless-enough)
 *  - unknown → UASTC (conservative). */
export function defaultBasisFormat(slot: TextureSlot): 'uastc' | 'etc1s' {
  if (slot === 'basecolor' || slot === 'emissive') return 'etc1s';
  return 'uastc';
}

/** Inspect `texture` against every material in `document` and
 *  return the matching slot. Returns `'unknown'` when no
 *  material binds this texture (orphan texture — encoder still
 *  treats it conservatively).
 *
 *  Priority order for multi-slot textures: normal > orm >
 *  basecolor > emissive. Higher-priority slots win because
 *  their format requirement is stricter (data-texture quality
 *  matters more than color-texture compression). */
export function classifyTextureSlot(
  texture: Texture,
  document: Document,
): TextureSlot {
  let best: TextureSlot = 'unknown';
  for (const material of document.getRoot().listMaterials()) {
    const slot = matchSlot(material, texture);
    if (slot === null) continue;
    if (priority(slot) > priority(best)) {
      best = slot;
    }
  }
  return best;
}

function priority(slot: TextureSlot): number {
  switch (slot) {
    case 'normal':
      return 4;
    case 'orm':
      return 3;
    case 'basecolor':
      return 2;
    case 'emissive':
      return 1;
    case 'unknown':
      return 0;
  }
}

function matchSlot(material: Material, texture: Texture): TextureSlot | null {
  if (material.getNormalTexture() === texture) return 'normal';
  if (material.getMetallicRoughnessTexture() === texture) return 'orm';
  if (material.getOcclusionTexture() === texture) return 'orm';
  if (material.getBaseColorTexture() === texture) return 'basecolor';
  if (material.getEmissiveTexture() === texture) return 'emissive';
  return null;
}
