// Type generator.
//
// Turns the (sprite ids, ui assets, model assets, data assets)
// tuple returned by the pipelines into a single TypeScript file
// written into the host app's source tree. The point is compile-
// time safety: a typo in `<Sprite name="hero_idl" />`,
// `<Model id="enemies_robt" />`, or
// `getWeapon('plasma_rifel')` should fail `tsc`, not silently
// fetch a nonexistent asset.
//
// Two-step, since the language-agnostic seam
// (docs/specs/language-agnostic-targets.md): the pipeline tuple is
// first reprojected into a language-NEUTRAL `AssetManifest`
// (`buildAssetManifest`) which forge writes as JSON; the TypeScript
// registry is then RENDERED from that manifest (`renderTsRegistry`
// — the `TsRegistryEmitter` body). A C++ / C# emitter is a sibling
// that reads the same manifest. The TS output is byte-for-byte what
// it always was — the manifest just made the input neutral.
//
// Output shape (kept compact and stable so diffs in version
// control are easy to read):
//
//   // Auto-generated by @unsupervised/forge — DO NOT EDIT
//   export type SpriteId = 'hero_idle' | 'enemies_toxic_slime';
//   export type UiImageId = 'backgrounds_menu' | 'icons_health';
//   export type ModelId = 'enemies_robot' | 'player_ship';
//   export type EnemiesRobotAnimations = 'idle' | 'run' | 'attack';
//
//   // Dynamically populated from weapons.json
//   export type WeaponId = 'plasma_rifle' | 'rusty_dagger';
//
//   export const ASSET_PATHS = { ... } as const;
//   export const MODEL_PATHS = { ... } as const;
//   export const MODEL_ANIMATIONS = { ... } as const;
//   export const DATA_PATHS = { ... } as const;

import {
  ASSET_MANIFEST_VERSION,
  type AssetManifest,
  type AssetManifestAudio,
  type AssetManifestAudioEntry,
  type AssetManifestDataEntry,
  type AssetManifestLocaleEntry,
  type AssetManifestModelEntry,
  type AssetManifestNavMeshEntry,
  type AssetManifestTileCacheEntry,
  type AssetManifestUiEntry,
} from '@unsupervised/schemas';
import type { AudioAssetMap } from '../pipelines/audioPipeline.js';
import type { DataAsset } from '../pipelines/dataPipeline.js';
import type { LocaleAsset } from '../pipelines/i18nPipeline.js';
import type { ModelAsset } from '../pipelines/modelPipeline.js';
import type {
  NavMeshAsset,
  TileCacheAsset,
} from '../pipelines/navmeshPipeline.js';
import type { UiAsset } from '../pipelines/uiPipeline.js';

const HEADER = [
  '// Auto-generated by @unsupervised/forge — DO NOT EDIT.',
  '//',
  '// Regenerate by running `forge assets` from the app root. The pipeline',
  '// reads from <input>/{images/{sprites,ui},models,data,audio}/ and emits',
  '// both the optimized binaries (into <output>/) and this file (into',
  '// <types>).',
  '',
].join('\n');

export interface GenerateAssetTypesArgs {
  outputPath: string;
  /** Where the neutral `AssetManifest` JSON is written. Optional so
   *  existing callers / tests that only want the TS registry keep
   *  working; the CLI always passes it. */
  manifestPath?: string;
  spriteIds: string[];
  uiAssets: UiAsset[];
  modelAssets: ModelAsset[];
  dataAssets: DataAsset[];
  audioAssets: AudioAssetMap;
  navMeshAssets: NavMeshAsset[];
  tileCacheAssets: TileCacheAsset[];
  localeAssets: LocaleAsset[];
  /** Sorted union of every key seen across every locale's
   *  catalog. Emitted as the `TranslationKey` literal union. */
  translationKeys: string[];
}

/**
 * Reproject the pipeline tuple into the language-neutral manifest.
 * A faithful rename — pipeline `identifier` / `publicPath` become the
 * manifest's `id` / `path`; the nested navmesh / tilecache / locale
 * manifests pass through unchanged (they already carry their own
 * schemas). Array order is preserved, so any downstream emitter
 * reproduces the pipelines' deterministic ordering.
 */
export function buildAssetManifest(
  args: GenerateAssetTypesArgs,
): AssetManifest {
  return {
    version: ASSET_MANIFEST_VERSION,
    sprites: [...args.spriteIds],
    ui: args.uiAssets.map((a) => ({ id: a.id, path: a.publicPath })),
    models: args.modelAssets.map((m) => ({
      id: m.identifier,
      path: m.path,
      animations: [...m.animations],
    })),
    data: args.dataAssets.map((d) => ({
      domain: d.domain,
      ids: [...d.ids],
      path: d.publicPath,
    })),
    audio: {
      sfx: args.audioAssets.sfx.map(toAudioEntry),
      music: args.audioAssets.music.map(toAudioEntry),
      environment: args.audioAssets.environment.map(toAudioEntry),
    },
    navmesh: args.navMeshAssets.map((a) => ({
      id: a.identifier,
      manifest: a.manifest,
    })),
    tileCache: args.tileCacheAssets.map((a) => ({
      id: a.identifier,
      manifest: a.manifest,
    })),
    locales: args.localeAssets.map((a) => ({
      id: a.bundle.config.id,
      bundle: a.bundle,
    })),
    translationKeys: [...args.translationKeys],
  };
}

function toAudioEntry(asset: {
  identifier: string;
  publicPath: string;
}): AssetManifestAudioEntry {
  return { id: asset.identifier, path: asset.publicPath };
}

/**
 * The `TsRegistryEmitter` body: render the neutral manifest into the
 * TypeScript asset registry. Output is byte-for-byte stable — apps
 * import id literals + path constants from here.
 */
export function renderTsRegistry(manifest: AssetManifest): string {
  const spriteUnion = renderUnion(manifest.sprites);
  const uiUnion = renderUnion(manifest.ui.map((a) => a.id));
  const modelUnion = renderUnion(manifest.models.map((m) => m.id));
  const animationTypeAliases = renderAnimationTypeAliases(manifest.models);
  const dataIdTypeAliases = renderDataIdTypeAliases(manifest.data);

  const uiPaths = renderUiPathRecord(manifest.ui);
  const modelPaths = renderModelPathRecord(manifest.models);
  const modelAnimations = renderModelAnimationRecord(manifest.models);
  const dataPaths = renderDataPathRecord(manifest.data);

  // Audio renders three per-bucket unions plus a unified `AudioId`
  // super-union. The latter is what high-level APIs (e.g.
  // `mixer.play(id)`) take, so they don't have to switch on the
  // bucket.
  const sfxUnion = renderUnion(manifest.audio.sfx.map((a) => a.id));
  const musicUnion = renderUnion(manifest.audio.music.map((a) => a.id));
  const environmentUnion = renderUnion(
    manifest.audio.environment.map((a) => a.id),
  );
  const audioPaths = renderAudioPathRecord(manifest.audio);

  // NavMesh tile manifests are emitted as full const literals
  // so apps construct `StreamingNavMesh.fromManifest(...)`
  // without a manifest fetch round-trip.
  const navMeshUnion = renderUnion(manifest.navmesh.map((a) => a.id));
  const navMeshManifests = renderNavMeshManifests(manifest.navmesh);

  // TileCache manifests are emitted alongside the streaming
  // manifests as a sibling const literal. Apps pick the
  // right one based on whether they want runtime obstacles.
  const tileCacheUnion = renderUnion(manifest.tileCache.map((a) => a.id));
  const tileCacheManifests = renderTileCacheManifests(manifest.tileCache);

  // i18n locale bundles are emitted as a full record so apps
  // call `bootI18n(world, { bundles: LOCALE_BUNDLES, ... })`
  // without a runtime fetch. Translation keys become a literal
  // union for autocomplete on `t('any.key', ...)`.
  const localeIdUnion = renderUnion(manifest.locales.map((a) => a.id));
  const translationKeyUnion = renderUnion(manifest.translationKeys);
  const localeBundles = renderLocaleBundles(manifest.locales);

  return `${HEADER}
export type SpriteId = ${spriteUnion};

export type UiImageId = ${uiUnion};

export type ModelId = ${modelUnion};

${animationTypeAliases}${dataIdTypeAliases}// Dynamically populated from <input>/audio/sfx/
export type SfxId = ${sfxUnion};

// Dynamically populated from <input>/audio/music/
export type MusicId = ${musicUnion};

// Dynamically populated from <input>/audio/environment/
export type EnvironmentId = ${environmentUnion};

export type AudioId = SfxId | MusicId | EnvironmentId;

// Dynamically populated from <input>/navmeshes/<world>/world.json (format: 'solo')
export type NavMeshWorldId = ${navMeshUnion};

// Dynamically populated from <input>/navmeshes/<world>/world.json (format: 'tilecache')
export type TileCacheWorldId = ${tileCacheUnion};

export const ASSET_PATHS = {
  spritesheet: '/sprites/spritesheet.json',
  ui: ${uiPaths},
} as const;

export const MODEL_PATHS = ${modelPaths} as const;

export const MODEL_ANIMATIONS = ${modelAnimations} as const;

export const DATA_PATHS = ${dataPaths} as const;

export const AUDIO_PATHS = ${audioPaths} as const;

export const NAVMESH_TILE_MANIFESTS = ${navMeshManifests} as const;

export const TILECACHE_MANIFESTS = ${tileCacheManifests} as const;

// Dynamically populated from <input>/i18n/<locale>.json
export type LocaleId = ${localeIdUnion};

// Dynamically populated from the union of all keys across every locale catalog
export type TranslationKey = ${translationKeyUnion};

export const LOCALE_BUNDLES = ${localeBundles} as const;
`;
}

/**
 * `'a' | 'b' | 'c'` — or `never` when there's nothing to union.
 * `never` is the right empty type: it both prevents accidental usage
 * (`<Sprite name={...} />` errors out with "argument of type 'string'
 * is not assignable to parameter of type 'never'") AND signals to
 * the reader that the bucket is intentionally empty.
 */
function renderUnion(ids: string[]): string {
  if (ids.length === 0) return 'never';
  return ids.map((id) => `'${escapeStringLiteral(id)}'`).join(' | ');
}

/**
 * Per-model animation type aliases — `EnemiesRobotAnimations`,
 * `PlayerShipAnimations`, etc. The PascalCase identifier comes from
 * the snake_case `model.id` so a model id like
 * `enemies_toxic_slime` produces `EnemiesToxicSlimeAnimations`.
 */
function renderAnimationTypeAliases(
  models: AssetManifestModelEntry[],
): string {
  if (models.length === 0) return '';
  const lines = models.map(
    (model) =>
      `export type ${snakeToPascal(model.id)}Animations = ${renderUnion(
        model.animations,
      )};`,
  );
  return lines.join('\n') + '\n\n';
}

/**
 * Per-data-domain id type aliases — `WeaponId`, `EnemyId`, etc.
 * The domain is the JSON filename minus `.json`; the type name is
 * the PascalCase singular plus `Id` (`weapons` → `Weapon` → `WeaponId`,
 * `enemies` → `Enemy` → `EnemyId`).
 */
function renderDataIdTypeAliases(data: AssetManifestDataEntry[]): string {
  if (data.length === 0) return '';
  const lines = data.map((asset) => {
    const typeName = `${snakeToPascal(singularize(asset.domain))}Id`;
    return `// Dynamically populated from ${asset.domain}.json\nexport type ${typeName} = ${renderUnion(asset.ids)};`;
  });
  return lines.join('\n\n') + '\n\n';
}

function renderUiPathRecord(ui: AssetManifestUiEntry[]): string {
  if (ui.length === 0) {
    // Empty record literal — keeps `ASSET_PATHS.ui` typed as
    // `Readonly<Record<never, never>>` rather than disappearing
    // entirely, so consumer code that destructures `ui` still
    // compiles when an app has no UI images yet.
    return '{}';
  }
  const entries = ui
    .map(
      (asset) =>
        `    '${escapeStringLiteral(asset.id)}': '${escapeStringLiteral(asset.path)}',`,
    )
    .join('\n');
  return `{\n${entries}\n  }`;
}

function renderModelPathRecord(models: AssetManifestModelEntry[]): string {
  if (models.length === 0) return '{}';
  const entries = models
    .map(
      (model) =>
        `  '${escapeStringLiteral(model.id)}': '${escapeStringLiteral(model.path)}',`,
    )
    .join('\n');
  return `{\n${entries}\n}`;
}

function renderModelAnimationRecord(
  models: AssetManifestModelEntry[],
): string {
  if (models.length === 0) return '{}';
  const entries = models
    .map((model) => {
      const animations = model.animations
        .map((name) => `'${escapeStringLiteral(name)}'`)
        .join(', ');
      return `  '${escapeStringLiteral(model.id)}': [${animations}],`;
    })
    .join('\n');
  return `{\n${entries}\n}`;
}

function renderDataPathRecord(data: AssetManifestDataEntry[]): string {
  if (data.length === 0) return '{}';
  const entries = data
    .map(
      (asset) =>
        `  ${asset.domain}: '${escapeStringLiteral(asset.path)}',`,
    )
    .join('\n');
  return `{\n${entries}\n}`;
}

/** Render the nested `AUDIO_PATHS` record:
 *
 *      {
 *        sfx: { 'laser_shoot': '/audio/sfx/laser_shoot.ogg', ... },
 *        music: { 'boss_theme': '/audio/music/boss_theme.ogg', ... },
 *        environment: { ... },
 *      } as const
 *
 *  Empty buckets emit `{}` rather than disappearing entirely so
 *  consumer destructuring patterns
 *  (`const { sfx } = AUDIO_PATHS`) keep compiling. */
function renderAudioPathRecord(audio: AssetManifestAudio): string {
  return [
    '{',
    `  sfx: ${renderAudioBucketRecord(audio.sfx)},`,
    `  music: ${renderAudioBucketRecord(audio.music)},`,
    `  environment: ${renderAudioBucketRecord(audio.environment)},`,
    '}',
  ].join('\n');
}

function renderAudioBucketRecord(assets: AssetManifestAudioEntry[]): string {
  if (assets.length === 0) return '{}';
  const entries = assets
    .map(
      (asset) =>
        `    '${escapeStringLiteral(asset.id)}': '${escapeStringLiteral(asset.path)}',`,
    )
    .join('\n');
  return `{\n${entries}\n  }`;
}

/** `enemies_toxic_slime` → `EnemiesToxicSlime`. Empty parts (from
 *  doubled underscores) are dropped, leading digits prefixed with
 *  `_` to remain a valid TypeScript type name. */
function snakeToPascal(snake: string): string {
  const pascal = snake
    .split('_')
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join('');
  return /^[0-9]/.test(pascal) ? `_${pascal}` : pascal;
}

/**
 * Best-effort English depluralization for data-domain type names.
 * The heuristic is intentionally narrow — it covers `weapons → weapon`,
 * `enemies → enemy`, `classes → class`, and bails to identity for
 * everything else. Authors with irregular plurals (`children → child`,
 * `data → datum`) should pick a regular filename.
 */
function singularize(word: string): string {
  if (word.length <= 1) return word;
  if (word.endsWith('ies') && word.length > 3) {
    return word.slice(0, -3) + 'y';
  }
  if (
    word.endsWith('xes') ||
    word.endsWith('ches') ||
    word.endsWith('shes') ||
    word.endsWith('sses') ||
    word.endsWith('zes')
  ) {
    return word.slice(0, -2);
  }
  if (word.endsWith('s') && !word.endsWith('ss')) {
    return word.slice(0, -1);
  }
  return word;
}

/** Escape characters that would terminate a single-quoted JS string
 *  literal. Sprite / model / animation / data names are author-
 *  controlled, and a malformed name shouldn't be allowed to break
 *  the generated module. */
function escapeStringLiteral(value: string): string {
  return value.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
}

/** Render the NAVMESH_TILE_MANIFESTS const literal. Each
 *  world's manifest is emitted in full so apps construct
 *  `StreamingNavMesh.fromManifest(...)` without a separate
 *  fetch round-trip. The values are JSON-trivial, so a
 *  recursive `JSON.stringify` is sufficient — TypeScript
 *  will preserve the literal types via `as const` on the
 *  outer object. */
function renderNavMeshManifests(
  navMesh: AssetManifestNavMeshEntry[],
): string {
  if (navMesh.length === 0) return '{}';
  const entries = navMesh
    .map(
      (asset) =>
        `  '${escapeStringLiteral(asset.id)}': ${JSON.stringify(asset.manifest, null, 2).replace(/^/gm, '  ').trimStart()},`,
    )
    .join('\n');
  return `{\n${entries}\n}`;
}

/** Render the LOCALE_BUNDLES const literal. Each entry's
 *  config + catalog are emitted in full so apps call
 *  `bootI18n(world, { bundles: LOCALE_BUNDLES, ... })`
 *  without a runtime fetch round-trip. Indented `JSON.stringify`
 *  output is human-readable for catalog diffs. */
function renderLocaleBundles(locales: AssetManifestLocaleEntry[]): string {
  if (locales.length === 0) return '{}';
  const entries = locales
    .map((asset) => {
      const json = JSON.stringify(asset.bundle, null, 2)
        .replace(/^/gm, '  ')
        .trimStart();
      return `  '${escapeStringLiteral(asset.id)}': ${json},`;
    })
    .join('\n');
  return `{\n${entries}\n}`;
}

/** Render the TILECACHE_MANIFESTS const literal. Mirrors
 *  the streaming variant's emission shape; the manifest
 *  shape is distinct (single `bundlePath` instead of
 *  per-tile binaries). Apps construct
 *  `TileCacheNavMesh.fromManifest(TILECACHE_MANIFESTS['my-world'])`. */
function renderTileCacheManifests(
  tileCache: AssetManifestTileCacheEntry[],
): string {
  if (tileCache.length === 0) return '{}';
  const entries = tileCache
    .map(
      (asset) =>
        `  '${escapeStringLiteral(asset.id)}': ${JSON.stringify(asset.manifest, null, 2).replace(/^/gm, '  ').trimStart()},`,
    )
    .join('\n');
  return `{\n${entries}\n}`;
}
