// Sprite atlas pipeline.
//
// Packs every image under `<input>/images/sprites/**` into a single
// webp atlas plus a JSON manifest describing each frame's location.
// This is the format consumed at runtime by Pixi/WebGL renderers:
// one texture upload, N draw calls — far faster than uploading N
// individual textures.
//
// Algorithm:
//   1. Glob source files. Read each one's intrinsic width/height
//      via `sharp().metadata()`.
//   2. Feed (w, h, file) tuples into MaxRectsPacker with a 2px
//      padding and a 2048×2048 max-bin size. Packing is a 2D
//      bin-packing approximation; the maxrects heuristic is cheap
//      and produces near-optimal layouts.
//   3. Take the FIRST bin (we publish a single atlas; if the input
//      overflows we warn — multi-bin output would force the
//      runtime to track which atlas each sprite lives in, which
//      we're not ready to support yet).
//   4. Use sharp to create a transparent canvas at the bin's exact
//      size and `composite()` every source image at its packed
//      (x, y) coordinates.
//   5. Encode the canvas as webp. Write a sibling JSON manifest.

import { extname, join, posix, relative } from 'node:path';
import fse from 'fs-extra';
import { glob } from 'glob';
import { MaxRectsPacker } from 'maxrects-packer';
import sharp from 'sharp';
import { pathToIdentifier } from '../utils/identifier.js';
import { dim, info, success, warn } from '../utils/log.js';

const SUPPORTED_EXTENSIONS = new Set(['.png', '.jpg', '.jpeg']);

/** Tunables. Bumping `MAX_ATLAS_SIZE` lets more sprites fit in one
 *  bin at the cost of GPU memory; 2048 is a safe ceiling for the
 *  WebGL 1.0 minimum guaranteed texture size. */
const MAX_ATLAS_SIZE = 2048;
/** Padding between packed sprites — prevents bilinear-filter
 *  bleeding from neighboring sprites at non-1× scales. */
const SPRITE_PADDING = 2;
const WEBP_QUALITY = 90;

const ATLAS_IMAGE_NAME = 'spritesheet.webp';
const ATLAS_MANIFEST_NAME = 'spritesheet.json';

interface PackerData {
  id: string;
  /** Absolute filesystem path — fed to sharp.composite as the
   *  `input` field. */
  absPath: string;
}

interface SpriteFrame {
  x: number;
  y: number;
  w: number;
  h: number;
}

/** Manifest written to spritesheet.json. Shape mirrors the de-facto
 *  TexturePacker convention so consumers familiar with that format
 *  recognize the layout immediately. */
export interface SpriteManifest {
  meta: {
    image: string;
    size: { w: number; h: number };
    scale: number;
  };
  frames: Record<string, SpriteFrame>;
}

export interface RunSpritePipelineArgs {
  inputDir: string;
  outputDir: string;
}

/**
 * Pack the sprite directory and return the list of packed ids.
 * Wipes `<output>/sprites/` so deleted sources don't leave stale
 * atlas slots behind.
 */
export async function runSpritePipeline(
  args: RunSpritePipelineArgs,
): Promise<string[]> {
  const spriteInputRoot = join(args.inputDir, 'images', 'sprites');
  const spriteOutputRoot = join(args.outputDir, 'sprites');

  if (!(await fse.pathExists(spriteInputRoot))) {
    dim(
      `Sprites: skipped (no ${posix.normalize('images/sprites')} directory under input)`,
    );
    return [];
  }

  const allFiles = await glob('**/*', {
    cwd: spriteInputRoot,
    nodir: true,
    posix: true,
  });

  const supported: string[] = [];
  for (const file of allFiles) {
    if (SUPPORTED_EXTENSIONS.has(extname(file).toLowerCase())) {
      supported.push(file);
    } else {
      warn(
        `Sprites: unsupported file type, skipping ${posix.join('images/sprites', file)}`,
      );
    }
  }

  if (supported.length === 0) {
    dim('Sprites: no images to process');
    await fse.emptyDir(spriteOutputRoot);
    return [];
  }

  await fse.emptyDir(spriteOutputRoot);
  info(
    `Sprites: measuring ${supported.length} image${supported.length === 1 ? '' : 's'}…`,
  );

  // 1. Probe each image for its intrinsic dimensions.
  const items: Array<{ data: PackerData; width: number; height: number }> = [];
  for (const relPath of supported) {
    const absPath = join(spriteInputRoot, relPath);
    try {
      const meta = await sharp(absPath).metadata();
      if (!meta.width || !meta.height) {
        warn(
          `Sprites: skipped ${posix.join('images/sprites', relPath)} — missing dimensions in metadata`,
        );
        continue;
      }
      items.push({
        data: { id: pathToIdentifier(relPath), absPath },
        width: meta.width,
        height: meta.height,
      });
    } catch (cause) {
      warn(
        `Sprites: failed to read ${posix.join('images/sprites', relPath)} — ${
          cause instanceof Error ? cause.message : String(cause)
        }`,
      );
    }
  }

  if (items.length === 0) {
    return [];
  }

  // 2. Pack. The third constructor arg is the inter-rect padding.
  //    `smart: true` lets the packer pick the smallest layout that
  //    still respects the max bin size.
  const packer = new MaxRectsPacker<PackerRect>(
    MAX_ATLAS_SIZE,
    MAX_ATLAS_SIZE,
    SPRITE_PADDING,
    { smart: true, pot: false, square: false, allowRotation: false },
  );
  for (const item of items) {
    packer.add(item.width, item.height, item.data);
  }

  if (packer.bins.length === 0) {
    warn('Sprites: packer produced zero bins — output will be empty');
    return [];
  }
  if (packer.bins.length > 1) {
    warn(
      `Sprites: ${items.length} sprites overflowed a single ${MAX_ATLAS_SIZE}×${MAX_ATLAS_SIZE} atlas; only the first bin (${packer.bins[0]?.rects.length} sprites) will be emitted`,
    );
  }

  const bin = packer.bins[0];
  if (!bin) {
    return [];
  }

  // 3. Compose the atlas.
  const composites = bin.rects.map((rect) => ({
    input: rect.data.absPath,
    left: rect.x,
    top: rect.y,
  }));

  const atlasOutputPath = join(spriteOutputRoot, ATLAS_IMAGE_NAME);
  await sharp({
    create: {
      width: bin.width,
      height: bin.height,
      channels: 4,
      background: { r: 0, g: 0, b: 0, alpha: 0 },
    },
  })
    .composite(composites)
    .webp({ quality: WEBP_QUALITY })
    .toFile(atlasOutputPath);

  // 4. Write the manifest.
  const frames: SpriteManifest['frames'] = {};
  for (const rect of bin.rects) {
    frames[rect.data.id] = {
      x: rect.x,
      y: rect.y,
      w: rect.width,
      h: rect.height,
    };
  }
  const manifest: SpriteManifest = {
    meta: {
      image: ATLAS_IMAGE_NAME,
      size: { w: bin.width, h: bin.height },
      scale: 1,
    },
    frames,
  };
  const manifestPath = join(spriteOutputRoot, ATLAS_MANIFEST_NAME);
  await fse.outputFile(manifestPath, JSON.stringify(manifest, null, 2));

  success(
    `Sprites: packed ${bin.rects.length} sprite${bin.rects.length === 1 ? '' : 's'} into ${ATLAS_IMAGE_NAME} (${bin.width}×${bin.height}) → ${relative(process.cwd(), spriteOutputRoot)}`,
  );

  // Stable, sorted ids for deterministic generated output.
  return bin.rects.map((rect) => rect.data.id).sort((a, b) => a.localeCompare(b));
}

// MaxRectsPacker's generic parameter constrains rects to
// `IRectangle` — a position+size shape with arbitrary extra fields.
// We attach our own `data` blob to each rect so the composer can
// recover the source filename without a second lookup.
interface PackerRect {
  x: number;
  y: number;
  width: number;
  height: number;
  data: PackerData;
  [extra: string]: unknown;
}
