// Filename → TypeScript-safe identifier.
//
// Used to derive both:
//   - Sprite ids (e.g. sprites/hero/idle.png  → 'hero_idle')
//   - UI image ids (e.g. ui/backgrounds/menu.png → 'backgrounds_menu')
//
// The id will be embedded in a generated TypeScript union type AND
// used as an object key in `ASSET_PATHS`. So it must be:
//   1. A valid TS identifier (we play it safe and additionally
//      ensure it starts with a letter or underscore).
//   2. Stable across runs and platforms — no random suffixing.

import { extname } from 'node:path';

const REPLACE_PATTERN = /[\s\-./\\]+/g;
const INVALID_CHAR_PATTERN = /[^a-zA-Z0-9_]/g;

/**
 * Convert a path like `enemies/toxic-slime.png` (relative to the
 * pipeline's bucket root) into a sanitized id like
 * `enemies_toxic_slime`.
 */
export function pathToIdentifier(relPath: string): string {
  const noExt = relPath.slice(0, relPath.length - extname(relPath).length);
  const collapsed = noExt.replace(REPLACE_PATTERN, '_');
  const cleaned = collapsed.replace(INVALID_CHAR_PATTERN, '_');
  // Identifiers may not start with a digit. Prefix with `_` if so.
  return /^[0-9]/.test(cleaned) ? `_${cleaned}` : cleaned;
}
