// i18n / localization pipeline.
//
// Reads `<input>/i18n/*.json` files. Each file is one locale
// bundle (config + catalog). The pipeline:
//
//   1. Reads every `.json` file under `<input>/i18n/`.
//   2. Validates each file against `LocaleBundleSchema` from
//      `@unsupervised/schemas`.
//   3. Validates cross-file invariants: every locale's catalog
//      keys are a subset of the UNION of all keys across all
//      locales. Missing keys (locale A has 'menu.start', locale
//      B doesn't) emit a warn line + fill from the global default
//      locale at codegen time.
//   4. Returns the parsed bundles + a sorted list of every key
//      seen across every locale. The type generator folds this
//      into the codegen output as a `TranslationKey` union and
//      the `LOCALE_BUNDLES` record.
//
// No public output binary — the catalog data lives inside the
// generated TS file (small enough at game-shipping scale; ~1 KB
// per locale per 100 messages, gzipped). Apps that ship 10k+
// messages per locale should switch to a runtime-fetch path,
// not bundle them all into the JS chunk — that's the deferred
// "huge-catalog mode" (OUT_OF_SCOPE until a narrative game
// reaches the threshold).

import { join, posix } from 'node:path';
import fse from 'fs-extra';
import { glob } from 'glob';
import type { LocaleBundle } from '@unsupervised/schemas';
import { LocaleBundleSchema } from '@unsupervised/schemas';
import { dim, info, warn } from '../utils/log.js';

export interface LocaleAsset {
  /** TS-safe identifier — e.g. `en`, `ja`, `zh_Hans_CN`. Used
   *  as the key in the generated `LOCALE_BUNDLES` record. */
  id: string;
  /** Original BCP-47 locale id (`'zh-Hans-CN'`). Used as the
   *  string the runtime store keys by. */
  localeId: string;
  /** The validated bundle. */
  bundle: LocaleBundle;
}

export interface I18nPipelineResult {
  locales: LocaleAsset[];
  /** Union of every key seen across every catalog, sorted
   *  alphabetically. The type generator uses this to emit
   *  the `TranslationKey` union. Empty when no locales found. */
  keys: string[];
  /** Default locale id (the alphabetically-first id when
   *  multiple are present, with `'en'` preferred if present).
   *  Used as the fill-from source for missing-key warnings. */
  defaultLocale: string | null;
}

export interface RunI18nPipelineArgs {
  inputDir: string;
  /** Strict mode rejects missing-key cases with an error
   *  instead of filling from the default. Apps that want a
   *  hard CI failure for incomplete translations opt in. */
  strict?: boolean;
}

/**
 * Find every `<input>/i18n/*.json` file, validate, return the
 * bundles + union-of-keys.
 *
 * Missing keys (locale X is missing a key locale Y has):
 *   - non-strict mode: warn + fill from the default locale's
 *     value at codegen time
 *   - strict mode: throw with a list of `(locale, key)` pairs
 *
 * Missing files are tolerated — running forge on a freshly-
 * cloned app with no `assets-raw/i18n/` directory should not
 * fail; it simply produces zero locales + zero keys.
 */
export async function runI18nPipeline(
  args: RunI18nPipelineArgs,
): Promise<I18nPipelineResult> {
  const i18nRoot = join(args.inputDir, 'i18n');
  if (!(await fse.pathExists(i18nRoot))) {
    dim(`i18n: skipped (no ${posix.normalize('i18n')} directory under input)`);
    return { locales: [], keys: [], defaultLocale: null };
  }

  const files = await glob('*.json', {
    cwd: i18nRoot,
    nodir: true,
    posix: true,
  });
  if (files.length === 0) {
    dim('i18n: no locale files to process');
    return { locales: [], keys: [], defaultLocale: null };
  }

  info(
    `i18n: processing ${files.length} locale${files.length === 1 ? '' : 's'}…`,
  );

  const locales: LocaleAsset[] = [];
  const allKeys = new Set<string>();
  for (const rel of files.sort()) {
    const abs = join(i18nRoot, rel);
    const raw = await fse.readFile(abs, 'utf8');
    let parsed: unknown;
    try {
      parsed = JSON.parse(raw);
    } catch (cause) {
      throw new Error(
        `i18n: ${rel} is not valid JSON — ${cause instanceof Error ? cause.message : String(cause)}`,
      );
    }
    const validation = LocaleBundleSchema.safeParse(parsed);
    if (!validation.success) {
      const issues = validation.error.issues
        .map((i) => `  - ${i.path.join('.') || '<root>'}: ${i.message}`)
        .join('\n');
      throw new Error(
        `i18n: ${rel} failed schema validation:\n${issues}`,
      );
    }
    const bundle = validation.data;
    const fileLocaleId = rel.replace(/\.json$/, '');
    if (bundle.config.id !== fileLocaleId) {
      throw new Error(
        `i18n: ${rel}: declared locale id '${bundle.config.id}' does not match filename. Rename file to '${bundle.config.id}.json' or change the bundle's config.id.`,
      );
    }
    for (const key of Object.keys(bundle.catalog)) {
      allKeys.add(key);
    }
    locales.push({
      id: localeIdToIdentifier(bundle.config.id),
      localeId: bundle.config.id,
      bundle,
    });
  }

  // Pick the default locale: prefer 'en', else the
  // alphabetically-first id. Used as the fill-from source.
  const ids = locales.map((l) => l.localeId);
  const defaultLocale = ids.includes('en') ? 'en' : ids.sort()[0] ?? null;
  const defaultBundle = locales.find((l) => l.localeId === defaultLocale);

  // Validate cross-locale coverage.
  const missing: Array<{ locale: string; keys: string[] }> = [];
  for (const asset of locales) {
    const have = new Set(Object.keys(asset.bundle.catalog));
    const gaps: string[] = [];
    for (const key of allKeys) {
      if (!have.has(key)) gaps.push(key);
    }
    if (gaps.length > 0) {
      missing.push({ locale: asset.localeId, keys: gaps.sort() });
    }
  }

  if (missing.length > 0) {
    if (args.strict) {
      const detail = missing
        .map(
          ({ locale, keys }) =>
            `  ${locale}: ${keys.length} missing — ${keys.slice(0, 5).join(', ')}${keys.length > 5 ? `, …(+${keys.length - 5} more)` : ''}`,
        )
        .join('\n');
      throw new Error(
        `i18n (strict): incomplete translations in ${missing.length} locale${missing.length === 1 ? '' : 's'}:\n${detail}`,
      );
    }
    if (!defaultBundle) {
      warn(
        `i18n: missing keys detected but no default locale available to fill — runtime fallback chain will return the key string for missing entries.`,
      );
    } else {
      for (const { locale, keys } of missing) {
        warn(
          `i18n: ${locale} is missing ${keys.length} key${keys.length === 1 ? '' : 's'} (filling from '${defaultLocale}'): ${keys.slice(0, 5).join(', ')}${keys.length > 5 ? `, …(+${keys.length - 5} more)` : ''}`,
        );
        const target = locales.find((l) => l.localeId === locale);
        if (!target) continue;
        const filled = { ...target.bundle.catalog };
        for (const key of keys) {
          const fallbackValue = defaultBundle.bundle.catalog[key];
          if (fallbackValue !== undefined) {
            filled[key] = fallbackValue;
          }
        }
        target.bundle = { ...target.bundle, catalog: filled };
      }
    }
  }

  return {
    locales,
    keys: [...allKeys].sort(),
    defaultLocale,
  };
}

/** BCP-47 locale id → TS-safe identifier. `'zh-Hans-CN'` →
 *  `'zh_Hans_CN'`. Mirrors `pathToIdentifier`'s posture but
 *  for the simpler shape locale ids take. */
export function localeIdToIdentifier(localeId: string): string {
  return localeId.replace(/-/g, '_');
}
