// Data pipeline.
//
// Reads every `.json` under `<input>/data/`, validates each one
// against the Zod schema the consuming app declares for its
// filename, and writes the minified JSON to `<output>/data/`. The
// id of every record (the `id` field of each object in the JSON,
// or the single object's `id`) is bubbled up to the type generator
// so the rest of the codebase can refer to data records via
// strictly-typed unions like `WeaponId = 'plasma_rifle' | 'rusty_dagger'`.
//
// Crash Early, Crash Loudly:
// Validation failures abort the build. There is no "skip and warn"
// fallback — malformed game data is a compile-time bug, not a soft
// runtime concern. The CLI prints a focused error pointing at the
// offending file and field, then `process.exit(1)`s.
//
// Why we keep this package zod-agnostic:
// The consumer authors their schemas using their own copy of zod.
// We only need to call `.parse(input)` on each schema, which is a
// stable structural method. Importing zod here would force a
// version alignment between forge and every consuming app — a
// constraint we don't want to inherit. Structural duck-typing
// (`ZodLikeSchema`) decouples them.

import { basename, dirname, extname, join, posix, relative } from 'node:path';
import { pathToFileURL } from 'node:url';
import { createJiti } from 'jiti';
import fse from 'fs-extra';
import { glob } from 'glob';
import { error, info, success, warn } from '../utils/log.js';

const SUPPORTED_EXTENSION = '.json';

/** Structural shape of any zod schema we care about. We only ever
 *  call `.parse(input)`, so we don't need the full zod type. */
interface ZodLikeSchema {
  parse(input: unknown): unknown;
}

/** Shape of `dataMap` exported by the consuming app's
 *  `data.config.ts`. Keys are JSON filenames; values are the Zod
 *  schemas to validate each file against. */
type DataMap = Record<string, ZodLikeSchema>;

/** A single zod issue, structurally — Zod's actual type lives in
 *  the consumer's package; we accept the minimum we need to format
 *  a useful error. */
interface ZodLikeIssue {
  path: ReadonlyArray<PropertyKey>;
  message: string;
}

/** A single validated data file's contribution to type generation. */
export interface DataAsset {
  /** TS-safe domain slug — e.g. `weapons` (from `weapons.json`). */
  domain: string;
  /** Public path under the app's `public/` dir, with a leading
   *  slash and POSIX separators — e.g. `/data/weapons.json`. */
  publicPath: string;
  /** The list of `id` field values extracted from the JSON's records. */
  ids: string[];
}

export interface RunDataPipelineArgs {
  inputDir: string;
  outputDir: string;
  /** Absolute path to the consuming app's data config (a TS or JS
   *  file exporting `dataMap`). May not exist, in which case we
   *  treat the data pipeline as a no-op. */
  dataConfigPath: string;
}

/**
 * Validate, minify, and id-extract every `.json` under
 * `<input>/data/`. Returns the structured input the type generator
 * needs to emit `WeaponId` / `EnemyId` / `DATA_PATHS`.
 *
 * Failure modes:
 *   - Config file missing → soft skip (the consumer hasn't opted
 *     into data validation yet; the pipeline exits cleanly).
 *   - Config file fails to load (syntax error, missing import) →
 *     red error, `process.exit(1)`.
 *   - Schema rejects a file → red error with file + path + message,
 *     `process.exit(1)`.
 *   - JSON file isn't listed in `dataMap` → soft warning, skip.
 */
export async function runDataPipeline(
  args: RunDataPipelineArgs,
): Promise<DataAsset[]> {
  const dataInputRoot = join(args.inputDir, 'data');
  const dataOutputRoot = join(args.outputDir, 'data');

  // 1. Load the data config via jiti. Soft-skip if it's missing —
  //    apps that haven't opted into data validation should still be
  //    able to use forge for sprites/UI/models without an empty
  //    `data.config.ts` chore.
  if (!(await fse.pathExists(args.dataConfigPath))) {
    info(
      `Data: skipped (no config at ${relative(process.cwd(), args.dataConfigPath)})`,
    );
    return [];
  }

  const dataMap = await loadDataMap(args.dataConfigPath);

  // 2. Glob the input directory.
  if (!(await fse.pathExists(dataInputRoot))) {
    info(
      `Data: skipped (no ${posix.normalize('data')} directory under input)`,
    );
    return [];
  }

  const allFiles = await glob('**/*', {
    cwd: dataInputRoot,
    nodir: true,
    posix: true,
  });

  const supported: string[] = [];
  for (const file of allFiles) {
    if (extname(file).toLowerCase() === SUPPORTED_EXTENSION) {
      supported.push(file);
    } else {
      warn(`Data: unsupported file type, skipping ${posix.join('data', file)}`);
    }
  }

  if (supported.length === 0) {
    info('Data: no JSON files to process');
    await fse.emptyDir(dataOutputRoot);
    return [];
  }

  await fse.emptyDir(dataOutputRoot);
  info(
    `Data: validating ${supported.length} JSON file${supported.length === 1 ? '' : 's'}…`,
  );

  // 3. Validate, minify, and extract ids per file.
  const assets: DataAsset[] = [];
  for (const relPath of supported) {
    const fileName = basename(relPath);
    const schema = dataMap[fileName];
    if (!schema) {
      warn(
        `Data: ${posix.join('data', relPath)} not in dataMap; skipping. Add it to data.config.ts to validate it.`,
      );
      continue;
    }

    const absInput = join(dataInputRoot, relPath);
    const raw = await fse.readFile(absInput, 'utf8');

    let parsed: unknown;
    try {
      parsed = JSON.parse(raw);
    } catch (cause) {
      reportFailureAndExit(
        relPath,
        `Invalid JSON: ${cause instanceof Error ? cause.message : String(cause)}`,
      );
    }

    let validated: unknown;
    try {
      validated = schema.parse(parsed);
    } catch (cause) {
      reportZodFailureAndExit(relPath, cause);
    }

    // 4. Write minified output. `JSON.stringify` with no spacing
    //    arg produces the smallest possible serialization.
    const absOutput = join(dataOutputRoot, fileName);
    await fse.ensureDir(dirname(absOutput));
    await fse.writeFile(absOutput, JSON.stringify(validated));

    // 5. Extract ids from the validated payload.
    const ids = extractIds(validated);

    assets.push({
      domain: deriveDomainSlug(fileName),
      publicPath: '/' + posix.join('data', fileName),
      ids,
    });
  }

  // Stable ordering for stable generated TS.
  assets.sort((a, b) => a.domain.localeCompare(b.domain));

  const totalIds = assets.reduce((acc, a) => acc + a.ids.length, 0);
  success(
    `Data: validated ${assets.length} file${assets.length === 1 ? '' : 's'} and indexed ${totalIds} record${totalIds === 1 ? '' : 's'} → ${relative(process.cwd(), dataOutputRoot)}`,
  );

  return assets;
}

/** Load and validate the consumer's `data.config.ts` via jiti. */
async function loadDataMap(configPath: string): Promise<DataMap> {
  // jiti compiles TS in-process. `fsCache: false` keeps the watch
  // mode honest — a developer editing data.config.ts shouldn't have
  // to wait for jiti's module cache to expire to see new schemas.
  const jiti = createJiti(pathToFileURL(import.meta.url).href, {
    fsCache: false,
    moduleCache: false,
  });

  let mod: unknown;
  try {
    mod = await jiti.import(configPath);
  } catch (cause) {
    error(
      `Failed to load data config at ${relative(process.cwd(), configPath)}\n  ${cause instanceof Error ? cause.message : String(cause)}`,
    );
    process.exit(1);
  }

  if (!mod || typeof mod !== 'object' || !('dataMap' in mod)) {
    error(
      `Data config at ${relative(process.cwd(), configPath)} must export a \`dataMap\` object.`,
    );
    process.exit(1);
  }

  const dataMap = (mod as { dataMap: unknown }).dataMap;
  if (!dataMap || typeof dataMap !== 'object') {
    error(
      `\`dataMap\` in ${relative(process.cwd(), configPath)} must be a non-null object.`,
    );
    process.exit(1);
  }
  return dataMap as DataMap;
}

/** Catch-all "build failed" error path for non-Zod failures. */
function reportFailureAndExit(relPath: string, message: string): never {
  error(`✗ ${posix.join('data', relPath)}\n  ${message}`);
  process.exit(1);
}

/** Format a Zod error as a focused punch list. Unformatted ZodError
 *  output is huge — `[0].damage: Expected number, received string`
 *  is what the developer actually needs. */
function reportZodFailureAndExit(relPath: string, cause: unknown): never {
  if (!isZodLikeError(cause)) {
    reportFailureAndExit(
      relPath,
      cause instanceof Error ? cause.message : String(cause),
    );
  }

  const issues = cause.issues
    .map((issue) => `  - ${formatPath(issue.path)}: ${issue.message}`)
    .join('\n');
  error(
    `✗ Validation failed for ${posix.join('data', relPath)}\n  issues:\n${issues}`,
  );
  process.exit(1);
}

/** Render a Zod issue path the way a developer reads JSON: array
 *  indices in brackets, object keys with dots. `[0].damage` instead
 *  of `0.damage`. */
function formatPath(path: ReadonlyArray<PropertyKey>): string {
  if (path.length === 0) return '<root>';
  let out = '';
  for (const segment of path) {
    if (typeof segment === 'number') {
      out += `[${segment}]`;
    } else {
      out += out === '' ? String(segment) : `.${String(segment)}`;
    }
  }
  return out;
}

function isZodLikeError(value: unknown): value is { issues: ZodLikeIssue[] } {
  if (!value || typeof value !== 'object' || !('issues' in value)) return false;
  const issues = (value as { issues: unknown }).issues;
  return Array.isArray(issues);
}

/** Walk an array of objects (or a single object) and pull out
 *  every string value attached to an `id` key. Anything else is
 *  ignored — non-id-bearing data files contribute zero records to
 *  the type generator, which is the correct empty case. */
function extractIds(data: unknown): string[] {
  const ids: string[] = [];
  if (Array.isArray(data)) {
    for (const item of data) {
      const id = readId(item);
      if (id !== undefined) ids.push(id);
    }
  } else {
    const id = readId(data);
    if (id !== undefined) ids.push(id);
  }
  return ids;
}

function readId(value: unknown): string | undefined {
  if (!value || typeof value !== 'object') return undefined;
  const id = (value as Record<string, unknown>).id;
  return typeof id === 'string' && id.length > 0 ? id : undefined;
}

/** `weapons.json` → `weapons`. The slug becomes both the
 *  `DATA_PATHS` record key and the source of the per-file type
 *  alias name (after PascalCase + singularize, in the generator). */
function deriveDomainSlug(fileName: string): string {
  const noExt = fileName.slice(0, fileName.length - extname(fileName).length);
  return noExt
    .replace(/[\s\-./\\]+/g, '_')
    .replace(/[^a-zA-Z0-9_]/g, '_')
    .toLowerCase();
}
