// Normal-from-height pipeline.
//
// Walks `<input>/textures/**/*.height.{png,jpg}` and emits a
// sibling `*.normal.png` next to each by running a Sobel filter
// over the source. Apps authoring rocky / brick / wood / terrain
// surfaces frequently have height maps from procedural sources
// (World Machine, Houdini, Substance Designer) but no matching
// normal maps; hand-baking through Substance is overkill for the
// simple case where the height map already encodes everything.
//
// Output: standard tangent-space normal map. Red = X derivative,
// Green = Y derivative, Blue = Z = 1.0 (flat baseline before
// vector normalization). Packed to PNG as RGB888 in the
// conventional [-1, 1] → [0, 255] mapping. Apps consuming the
// normal via Three's `MeshStandardMaterial.normalMap` get the
// expected lighting response without further setup.
//
// Strength: a `normalStrength` knob is exposed per file via a
// suffix syntax (`*.height.png` → strength=1.0; future:
// `*.height.s2.png` for strength 2.0). v1 ships strength=1 only;
// authoring scaled normals via the suffix is a follow-up when an
// app asks.
//
// Skipping convention: if a sibling `*.normal.{png,jpg}` already
// exists next to the source height map, the pipeline skips the
// bake. Apps painting their own normal maps for stylized control
// keep priority over the auto-bake.

import { extname, join, posix, relative, sep } from 'node:path';
import fse from 'fs-extra';
import { glob } from 'glob';
import sharp from 'sharp';
import { pathToIdentifier } from '../utils/identifier.js';
import { dim, info, success, warn } from '../utils/log.js';

/** Supported height-map extensions. */
const SUPPORTED_EXTENSIONS = new Set(['.png', '.jpg', '.jpeg']);

export interface NormalAsset {
  /** TS-safe identifier — e.g. `terrain_rocks_normal`. */
  identifier: string;
  /** Public path under `/textures/`, POSIX separators, leading
   *  slash — e.g. `/textures/terrain/rocks.normal.png`. */
  path: string;
}

export interface RunNormalFromHeightPipelineArgs {
  inputDir: string;
  outputDir: string;
}

/** Generate a tangent-space normal map for every
 *  `*.height.{png,jpg}` under `<input>/textures/`. Existing
 *  hand-painted `*.normal.{png,jpg}` siblings win — apps that
 *  authored their own normals stay authoritative. */
export async function runNormalFromHeightPipeline(
  args: RunNormalFromHeightPipelineArgs,
): Promise<NormalAsset[]> {
  const inputRoot = join(args.inputDir, 'textures');
  const outputRoot = join(args.outputDir, 'textures');

  if (!(await fse.pathExists(inputRoot))) {
    dim('NormalFromHeight: skipped (no textures directory under input)');
    return [];
  }

  const allHeightFiles = await glob('**/*.height.*', {
    cwd: inputRoot,
    nodir: true,
    posix: true,
  });

  const supported: string[] = [];
  for (const file of allHeightFiles) {
    if (SUPPORTED_EXTENSIONS.has(extname(file).toLowerCase())) {
      supported.push(file);
    } else {
      warn(
        `NormalFromHeight: unsupported file type, skipping ${posix.join('textures', file)}`,
      );
    }
  }

  if (supported.length === 0) {
    dim('NormalFromHeight: no .height.* files to process');
    return [];
  }

  info(
    `NormalFromHeight: processing ${supported.length} height map${supported.length === 1 ? '' : 's'}…`,
  );

  const assets: NormalAsset[] = [];

  for (const relPath of supported) {
    const inAbs = join(inputRoot, relPath);
    // `terrain/rocks.height.png` → `terrain/rocks.normal.png`.
    const relNormal = relPath.replace(
      /\.height\.(png|jpe?g)$/i,
      '.normal.png',
    );
    const outAbs = join(outputRoot, relNormal);

    // Hand-painted normal map next to the source wins. Look for
    // a sibling with EITHER `.normal.png` or `.normal.jpg`.
    const handPaintedCandidates = [
      relPath.replace(/\.height\.(png|jpe?g)$/i, '.normal.png'),
      relPath.replace(/\.height\.(png|jpe?g)$/i, '.normal.jpg'),
    ];
    let handPaintedExists = false;
    for (const candidate of handPaintedCandidates) {
      if (await fse.pathExists(join(inputRoot, candidate))) {
        handPaintedExists = true;
        break;
      }
    }
    if (handPaintedExists) {
      dim(
        `NormalFromHeight: hand-painted normal map exists next to ${posix.join('textures', relPath)} — skipping auto-bake.`,
      );
      continue;
    }

    try {
      // Read the height map as a single-channel grayscale raw
      // buffer. Sobel operates on luminance only — RGB sources
      // collapse to grayscale via the standard 0.299/0.587/0.114
      // weights (sharp's default `.grayscale()` matches this).
      const { data, info: raster } = await sharp(inAbs)
        .grayscale()
        .raw()
        .toBuffer({ resolveWithObject: true });
      const rgbNormal = sobelNormalFromHeight(
        data,
        raster.width,
        raster.height,
      );
      await fse.ensureDir(join(outAbs, '..'));
      await sharp(rgbNormal, {
        raw: {
          width: raster.width,
          height: raster.height,
          channels: 3,
        },
      })
        .png()
        .toFile(outAbs);
      assets.push({
        identifier: pathToIdentifier(relNormal),
        path:
          '/' +
          posix.join(
            'textures',
            relNormal.split(sep).join(posix.sep),
          ),
      });
    } catch (cause) {
      warn(
        `NormalFromHeight: failed to bake ${posix.join('textures', relPath)} — ${
          cause instanceof Error ? cause.message : String(cause)
        }`,
      );
    }
  }

  assets.sort((a, b) => a.identifier.localeCompare(b.identifier));

  success(
    `NormalFromHeight: baked ${assets.length} normal map${assets.length === 1 ? '' : 's'} → ${relative(process.cwd(), outputRoot)}`,
  );

  return assets;
}

/** Compute a tangent-space normal map from a single-channel
 *  height buffer via a 3×3 Sobel kernel.
 *
 *  Sobel kernel (X-derivative; Y-derivative is its transpose):
 *      ⎡ -1  0  +1 ⎤
 *  Gx =⎢ -2  0  +2 ⎥
 *      ⎣ -1  0  +1 ⎦
 *
 *  Boundary handling: rows / columns at the edge of the image
 *  use clamp-to-edge (the kernel reads the same row/column for
 *  out-of-bounds samples). This produces a flat normal at the
 *  edge — acceptable for tileable textures; non-tileable inputs
 *  see ~1-pixel seams that hide behind the texture's edge mask
 *  in practice.
 *
 *  Strength: the X / Y derivatives are scaled so that a 1-unit
 *  height delta over 1 pixel produces a 45° tangent. The
 *  resulting normal is normalized to unit length before packing,
 *  so the strength is implicitly "uniform across the kernel" —
 *  consistent with how Substance / xNormal bake at default
 *  strength.
 *
 *  Output: RGB888 with the standard [-1, 1] → [0, 255] mapping.
 *  Blue channel is set so that the normal is unit-length after
 *  unpacking; the formula is `B = sqrt(1 - X² - Y²)` mapped to
 *  [0.5, 1.0] in the output. */
export function sobelNormalFromHeight(
  height: Uint8Array,
  width: number,
  rows: number,
): Uint8Array {
  const out = new Uint8Array(width * rows * 3);
  // Scale factor: maps the [-4, +4] Sobel output range (worst
  // case after kernel weighting) to [-1, 1] before normalization.
  // The 1/255 factor converts the height samples from byte range
  // to [0, 1].
  const SCALE = 1.0 / (4.0 * 255.0);
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < width; x++) {
      const tl = sample(height, x - 1, y - 1, width, rows);
      const tm = sample(height, x, y - 1, width, rows);
      const tr = sample(height, x + 1, y - 1, width, rows);
      const ml = sample(height, x - 1, y, width, rows);
      const mr = sample(height, x + 1, y, width, rows);
      const bl = sample(height, x - 1, y + 1, width, rows);
      const bm = sample(height, x, y + 1, width, rows);
      const br = sample(height, x + 1, y + 1, width, rows);
      // Sobel X / Y in image-space coordinates (Y grows
      // downward). The normal's Y axis flips because we want
      // tangent-space "up" to be image-space "up" (Y inverted).
      const gx = (tr + 2 * mr + br - tl - 2 * ml - bl) * SCALE;
      const gy = (bl + 2 * bm + br - tl - 2 * tm - tr) * SCALE;
      const nx = -gx;
      const ny = -gy;
      const nz = 1.0;
      const invLen = 1.0 / Math.sqrt(nx * nx + ny * ny + nz * nz);
      const rx = nx * invLen;
      const ry = ny * invLen;
      const rz = nz * invLen;
      const idx = (y * width + x) * 3;
      out[idx + 0] = packNormalChannel(rx);
      out[idx + 1] = packNormalChannel(ry);
      out[idx + 2] = packNormalChannel(rz);
    }
  }
  return out;
}

function sample(
  buf: Uint8Array,
  x: number,
  y: number,
  width: number,
  rows: number,
): number {
  // Clamp-to-edge boundary handling.
  const cx = x < 0 ? 0 : x >= width ? width - 1 : x;
  const cy = y < 0 ? 0 : y >= rows ? rows - 1 : y;
  return buf[cy * width + cx]!;
}

function packNormalChannel(v: number): number {
  // [-1, 1] → [0, 255]
  const scaled = (v * 0.5 + 0.5) * 255;
  return Math.max(0, Math.min(255, Math.round(scaled)));
}
