// KTX2 / Basis Universal texture transform for gltf-transform.
//
// Walks every texture in the document, classifies its material
// slot (normal / ORM / basecolor / emissive), encodes via the
// chosen Basis Universal codec (UASTC for data, ETC1S for color),
// and registers the `KHR_texture_basisu` extension so renderers
// that wire a `KTX2Loader` automatically pick up the encoded
// payload.
//
// Why a custom transform (not `@gltf-transform/functions`'
// built-in `textureCompress`):
//   `textureCompress` is sharp-based and only supports JPG / PNG
//   / WebP / AVIF. KTX2 / Basis Universal is a GPU-native
//   compressed-texture container; encoding is done via the
//   basisu binary (or its WASM equivalent). gltf-transform's CLI
//   has a `toktx()` transform but it requires the toktx native
//   binary installed system-wide; this transform uses
//   `@gpu-tex-enc/basis` instead, which bundles the binary per
//   platform via npm (no `brew install` etc.).
//
// Per-texture format selection:
//   See [textureClassification.ts](../textureClassification.ts)
//   for the slot-priority table. Apps that need to override the
//   defaults (e.g., compress every texture with UASTC for
//   maximum quality) pass `overrides` in the options.

import type { Transform } from '@gltf-transform/core';
import { KHRTextureBasisu } from '@gltf-transform/extensions';
import {
  encodeBasisU,
  type BasisFormat,
} from '../encoders/basisEncoder.js';
import {
  classifyTextureSlot,
  defaultBasisFormat,
  type TextureSlot,
} from '../textureClassification.js';
import { warn } from '../utils/log.js';

export interface Ktx2TransformOptions {
  /** Per-slot encoder format overrides. Keys are slot names;
   *  values pick the codec. Leave undefined for defaults
   *  (basecolor / emissive → ETC1S; everything else → UASTC). */
  overrides?: Partial<Record<TextureSlot, BasisFormat>>;
  /** Per-format quality knob.
   *  - UASTC: 0-4 (basisu's `-uastc_level`). Default 2.
   *  - ETC1S: 1-255 (basisu's `-q`). Default 128. */
  quality?: { uastc?: number; etc1s?: number };
  /** Generate mipmaps inside the KTX2 container. Default true.
   *  Set false for UI / decal textures that never minify. */
  mipmaps?: boolean;
  /** Pluggable encoder for tests + future package swaps. v1 uses
   *  the default `encodeBasisU` from `../encoders/basisEncoder.js`. */
  encoder?: typeof encodeBasisU;
}

/** Build the gltf-transform `Transform` function. Returns the
 *  function for use with `document.transform(ktx2Transform(...))`. */
export function ktx2Transform(
  opts: Ktx2TransformOptions = {},
): Transform {
  const encode = opts.encoder ?? encodeBasisU;
  return async (document) => {
    const textures = document.getRoot().listTextures();
    if (textures.length === 0) return;

    // Register the extension. `setRequired(true)` would force
    // renderers without KTX2 support to refuse the model; we
    // leave it OFF so apps using KTX2Loader transcoded outputs
    // alongside legacy non-KTX2 viewers (e.g., glTF Validator,
    // online previewers) still get a graceful fallback.
    const basisu = document
      .createExtension(KHRTextureBasisu)
      .setRequired(false);

    for (const texture of textures) {
      const slot = classifyTextureSlot(texture, document);
      const format =
        opts.overrides?.[slot] ?? defaultBasisFormat(slot);

      const inputBytes = texture.getImage();
      if (!inputBytes || inputBytes.length === 0) {
        // Texture with no embedded image (URI-only reference?).
        // Skip — basisu can't operate on missing data.
        continue;
      }
      const mimeType = texture.getMimeType();
      if (mimeType === 'image/ktx2') {
        // Already KTX2-encoded — happens when re-running the
        // pipeline on its own output (e.g., during dev). Skip.
        continue;
      }

      try {
        const encoded = await encode(inputBytes, {
          format,
          qualityLevel:
            format === 'uastc' ? opts.quality?.uastc : opts.quality?.etc1s,
          mipmaps: opts.mipmaps ?? true,
        });
        texture.setImage(encoded);
        texture.setMimeType('image/ktx2');
        // Strip any URI — the encoded payload now lives in the
        // GLB binary chunk, not at the original URL.
        texture.setURI('');
      } catch (cause) {
        warn(
          `KTX2: failed to encode texture (slot=${slot}, format=${format}) — ${
            cause instanceof Error ? cause.message : String(cause)
          }`,
        );
      }
    }

    // Keep the extension registered even if no texture used it
    // (defensive — gltf-transform serializers may strip unused
    // extensions otherwise).
    void basisu;
  };
}
