// Tiny ANSI-color console helpers.
//
// Inlined here on purpose — `chalk` and friends would be a multi-MB
// dependency for what amounts to a handful of escape codes. The
// terminal output of `forge` is short, structured, and easy to read.

const ESC = '';
const RESET = `${ESC}[0m`;
const DIM = `${ESC}[2m`;
const CYAN = `${ESC}[36m`;
const GREEN = `${ESC}[32m`;
const YELLOW = `${ESC}[33m`;
const RED = `${ESC}[31m`;

const PREFIX = `${CYAN}[Forge]${RESET}`;

export function info(message: string): void {
  console.log(`${PREFIX} ${message}`);
}

export function success(message: string): void {
  console.log(`${PREFIX} ${GREEN}${message}${RESET}`);
}

export function warn(message: string): void {
  console.warn(`${PREFIX} ${YELLOW}${message}${RESET}`);
}

export function error(message: string): void {
  console.error(`${PREFIX} ${RED}${message}${RESET}`);
}

export function dim(message: string): void {
  console.log(`${PREFIX} ${DIM}${message}${RESET}`);
}
