// The asset-registry orchestration step forge's CLI calls.
//
// One run: reproject the pipeline tuple into the neutral `AssetManifest`,
// write it as JSON (the language-agnostic source of truth), then render the
// per-language bindings the game's `.atelier/target.json` requested via the
// registry-emitter seam. `['typescript']` (the default) reproduces exactly
// what forge always emitted.

import { relative } from 'node:path';
import fse from 'fs-extra';
import { info } from '../utils/log.js';
import { buildAssetManifest, type GenerateAssetTypesArgs } from './typeGenerator.js';
import {
  resolveRegistryEmitters,
  type ResolvedRegistryEmitter,
} from './registryEmitters.js';

export async function generateAssetTypes(
  args: GenerateAssetTypesArgs,
  emitters?: ResolvedRegistryEmitter[],
): Promise<void> {
  // Default to the built-in TS emitter writing to `outputPath` — so callers
  // that don't resolve a target (tests, direct callers) get today's behavior.
  const resolved =
    emitters ??
    resolveRegistryEmitters(['typescript'], {
      defaultOutputPath: args.outputPath,
      gameRoot: process.cwd(),
    });

  const manifest = buildAssetManifest(args);

  // The neutral manifest is written first — it is the source of truth every
  // language binding reads (external emitters read it off disk).
  if (args.manifestPath !== undefined) {
    await fse.outputFile(
      args.manifestPath,
      JSON.stringify(manifest, null, 2) + '\n',
    );
  }

  for (const { emitter, outputPath } of resolved) {
    await emitter.emit({
      manifest,
      manifestPath: args.manifestPath,
      outputPath,
    });
  }

  const animationCount = manifest.models.reduce(
    (acc, m) => acc + m.animations.length,
    0,
  );
  const dataIdCount = manifest.data.reduce((acc, d) => acc + d.ids.length, 0);
  const audioIdCount =
    manifest.audio.sfx.length +
    manifest.audio.music.length +
    manifest.audio.environment.length;
  const navMeshTileCount = manifest.navmesh.reduce(
    (acc, nm) => acc + nm.manifest.tiles.length,
    0,
  );
  const tileCacheCellCount = manifest.tileCache.reduce(
    (acc, tc) => acc + tc.manifest.tiles.length,
    0,
  );
  info(
    `Types: wrote ${manifest.sprites.length} sprite id${manifest.sprites.length === 1 ? '' : 's'} + ${manifest.ui.length} ui id${manifest.ui.length === 1 ? '' : 's'} + ${manifest.models.length} model id${manifest.models.length === 1 ? '' : 's'} (${animationCount} animation${animationCount === 1 ? '' : 's'}) + ${manifest.data.length} data domain${manifest.data.length === 1 ? '' : 's'} (${dataIdCount} record${dataIdCount === 1 ? '' : 's'}) + ${audioIdCount} audio id${audioIdCount === 1 ? '' : 's'} + ${manifest.navmesh.length} navmesh world${manifest.navmesh.length === 1 ? '' : 's'} (${navMeshTileCount} tile${navMeshTileCount === 1 ? '' : 's'}) + ${manifest.tileCache.length} tilecache world${manifest.tileCache.length === 1 ? '' : 's'} (${tileCacheCellCount} cell${tileCacheCellCount === 1 ? '' : 's'}) + ${manifest.locales.length} locale${manifest.locales.length === 1 ? '' : 's'} (${manifest.translationKeys.length} translation key${manifest.translationKeys.length === 1 ? '' : 's'}) → ${relative(process.cwd(), args.outputPath)}`,
  );
}
