// `forge` CLI entry point.
//
// Defines a single `assets` command that orchestrates the pipelines
// and the type generator. The shape is deliberately thin — the
// actual work lives in `src/pipelines/*` and
// `src/generator/typeGenerator.ts`. This file is plumbing.
//
// Folder-as-Configuration: nothing about asset MEANING lives here.
// The CLI just routes between five well-known buckets:
//
//   <input>/images/sprites/  →  WebGL atlas
//   <input>/images/ui/       →  standalone UI webps
//   <input>/models/          →  Draco-compressed GLB models
//   <input>/data/            →  Zod-validated minified JSON
//   <input>/audio/           →  FFmpeg → Ogg Vorbis, by category
//
// Adding a sixth bucket means writing a sixth pipeline and wiring
// it in below — never editing this file's CLI surface.

import { dirname, join, resolve } from 'node:path';
import chokidar from 'chokidar';
import { Command } from 'commander';
import { generateAssetTypes } from './generator/assetRegistry.js';
import { resolveRegistryEmitters } from './generator/registryEmitters.js';
import { resolveTargetForRoot } from './target/resolveTarget.js';
import { runAudioPipeline } from './pipelines/audioPipeline.js';
import { runDataPipeline } from './pipelines/dataPipeline.js';
import { runI18nPipeline } from './pipelines/i18nPipeline.js';
import { runModelPipeline } from './pipelines/modelPipeline.js';
import { runNavMeshPipeline } from './pipelines/navmeshPipeline.js';
import { runNormalFromHeightPipeline } from './pipelines/normalFromHeightPipeline.js';
import { runSpritePipeline } from './pipelines/spritePipeline.js';
import { runUiPipeline } from './pipelines/uiPipeline.js';
import { dim, error, info, success } from './utils/log.js';

interface AssetsCommandOptions {
  input: string;
  output: string;
  types: string;
  manifest: string;
  dataConfig: string;
  watch?: boolean;
}

/** Debounce for chokidar event coalescing. Dropping a folder of
 *  20 files into VSCode's file explorer fires ~20 `add` events
 *  within ~50ms; without this we'd rerun the full pipeline 20
 *  times back-to-back. Bumped from 300 → 500ms once the audio
 *  pipeline came online: dragging a fresh `.wav` from a DAW into
 *  the watch tree triggers a write-then-flush cycle that can take
 *  hundreds of ms even after `awaitWriteFinish`, and we don't
 *  want a half-flushed file launching ffmpeg. */
const WATCH_DEBOUNCE_MS = 500;

const program = new Command();

program
  .name('forge')
  .description('Asset pipeline for Atelier — sprite atlases, UI webps, generated TS.')
  .version('0.0.0');

program
  .command('assets')
  .description('Run the asset pipeline once, or rerun on file changes with --watch.')
  .option('-i, --input <path>', 'directory holding raw assets', './assets-raw')
  .option('-o, --output <path>', 'directory to write processed assets', './public')
  .option('-t, --types <path>', 'path to write the generated TS file', './lib/generated/assets.ts')
  .option(
    '-m, --manifest <path>',
    'path to write the neutral asset manifest JSON (default: alongside --types)',
  )
  .option(
    '-d, --data-config <path>',
    "path to the consuming app's data.config.ts (filename → Zod schema map)",
    './data.config.ts',
  )
  .option('-w, --watch', 'watch the input directory and rebuild on change', false)
  .action(async (rawOpts: Omit<AssetsCommandOptions, 'manifest'> & { manifest?: string }) => {
    const types = resolve(process.cwd(), rawOpts.types);
    const opts: AssetsCommandOptions = {
      input: resolve(process.cwd(), rawOpts.input),
      output: resolve(process.cwd(), rawOpts.output),
      types,
      // The neutral manifest defaults to sitting beside the TS registry
      // (`lib/generated/asset-manifest.json`) — the language binding and
      // its source of truth stay together.
      manifest:
        rawOpts.manifest !== undefined
          ? resolve(process.cwd(), rawOpts.manifest)
          : join(dirname(types), 'asset-manifest.json'),
      dataConfig: resolve(process.cwd(), rawOpts.dataConfig),
      watch: rawOpts.watch ?? false,
    };

    info(`input       → ${opts.input}`);
    info(`output      → ${opts.output}`);
    info(`types       → ${opts.types}`);
    info(`manifest    → ${opts.manifest}`);
    info(`data config → ${opts.dataConfig}`);

    await runOnce(opts);

    if (opts.watch) {
      startWatcher(opts);
    }
  });

program.parseAsync(process.argv).catch((cause: unknown) => {
  error(cause instanceof Error ? cause.stack ?? cause.message : String(cause));
  process.exit(1);
});

/** One-shot pipeline run. All five pipelines fire in parallel since
 *  they read disjoint subdirectories and write disjoint output paths;
 *  the type generator joins their results.
 *
 *  Heavy legs: model processing (Draco WASM boot + geometry
 *  compression) and audio processing (multiple ffmpeg encodes,
 *  internally chunked at concurrency 2). Running both concurrently
 *  with the cheap sprite/UI/data passes overlaps their CPU + I/O
 *  with disk work the others are doing anyway. */
async function runOnce(opts: AssetsCommandOptions): Promise<void> {
  const startedAt = Date.now();
  try {
    // NO GENERATION RUNS HERE (removed 2026-08-24). Forge encodes what
    // exists; it never creates it, and it never spends money.
    //
    // All three generation pipelines — 3D/art (asset-gen), audio
    // (audio-gen), localization (loc-gen) — are driven from the Workbench
    // and from their own CLIs, which carry the same orchestrators plus
    // `review` / `drift` / `forecast` / `check`. Keeping a second trigger
    // inside the build meant `pnpm forge` could silently bill a vendor
    // API, which is the one thing a build step must never do: a build has
    // to be safe to run on any machine, any number of times, including in
    // CI, by someone who never authenticated with anyone.
    //
    // Generated bytes flow through unchanged. A GLB lands beside its
    // sidecar under `<input>/models/` and modelPipeline encodes it; audio
    // lands beside its sidecar and audioPipeline transcodes it to Ogg;
    // locale bundles land in `<input>/i18n/` and i18nPipeline folds them
    // into the typed catalog.

    // Normal-from-height runs in the parallel block too. It does
    // its own IO under `<input>/textures/` + emits to
    // `<output>/textures/` — disjoint from every other pipeline's
    // dirs, so no contention. Its output isn't included in the
    // typed asset registry today (apps reference normal maps by
    // path mirroring the source height map's id); revisit if
    // app-side ergonomics demand a `NormalMapId` union.
    const [
      spriteIds,
      uiAssets,
      modelAssets,
      dataAssets,
      audioAssets,
      _normalAssets,
      i18nResult,
    ] = await Promise.all([
      runSpritePipeline({ inputDir: opts.input, outputDir: opts.output }),
      runUiPipeline({ inputDir: opts.input, outputDir: opts.output }),
      runModelPipeline({ inputDir: opts.input, outputDir: opts.output }),
      runDataPipeline({
        inputDir: opts.input,
        outputDir: opts.output,
        dataConfigPath: opts.dataConfig,
      }),
      runAudioPipeline({ inputDir: opts.input, outputDir: opts.output }),
      runNormalFromHeightPipeline({
        inputDir: opts.input,
        outputDir: opts.output,
      }),
      runI18nPipeline({ inputDir: opts.input }),
    ]);
    void _normalAssets;

    // NavMesh runs serially AFTER the other pipelines.
    // recast-navigation's WASM module aborts when initialized
    // alongside Sharp / Draco / ffmpeg in the same process
    // (proven by experiment — `Aborted()` from inside
    // `init()` when other heavy WASM modules are
    // simultaneously loading). Running it after the others
    // have settled sidesteps the WASM-collision issue.
    // Per-tile bake is fast (single-digit ms each) so the
    // serial step adds little overhead.
    const navMeshResult = await runNavMeshPipeline({
      inputDir: opts.input,
      outputDir: opts.output,
    });

    // Which language bindings to render from the neutral manifest — from
    // the game's `.atelier/target.json` (default `['typescript']`). Resolved
    // (unknown built-in throws) before anything is written.
    const target = await resolveTargetForRoot(process.cwd());
    const emitters = resolveRegistryEmitters(target.registryEmitters, {
      defaultOutputPath: opts.types,
      gameRoot: process.cwd(),
    });

    await generateAssetTypes({
      outputPath: opts.types,
      manifestPath: opts.manifest,
      spriteIds,
      uiAssets,
      modelAssets,
      dataAssets,
      audioAssets,
      navMeshAssets: navMeshResult.navMesh,
      tileCacheAssets: navMeshResult.tileCache,
      localeAssets: i18nResult.locales,
      translationKeys: i18nResult.keys,
    }, emitters);

    success(`Done in ${Date.now() - startedAt}ms.`);
  } catch (cause) {
    error(
      `Pipeline failed — ${cause instanceof Error ? cause.message : String(cause)}`,
    );
    if (!opts.watch) {
      process.exitCode = 1;
    }
    // In watch mode, swallow the error so the watcher stays alive
    // for the next save.
  }
}

/** Spawn a chokidar watcher on the input directory and rebuild on
 *  change. Holds the process open via chokidar's internal handles —
 *  no manual `setInterval` needed.
 *
 *  Watch scope: chokidar.watch is recursive by default, so the single
 *  `opts.input` watcher covers `<input>/images/sprites/`,
 *  `<input>/images/ui/`, `<input>/models/`, `<input>/data/`, AND
 *  `<input>/audio/` — adding/changing/removing any `.gltf`, `.glb`,
 *  `.png`, `.jpg`, `.json`, `.wav`, `.mp3`, `.flac`, or `.m4a`
 *  triggers the same debounced rebuild. We also watch the data
 *  config file so editing a Zod schema retriggers validation. */
function startWatcher(opts: AssetsCommandOptions): void {
  info(`Watching ${opts.input} for changes…`);

  const watcher = chokidar.watch([opts.input, opts.dataConfig], {
    ignoreInitial: true,
    awaitWriteFinish: {
      // Sharp / gltf-transform can fail if they read a file that's
      // still being flushed by the writer. `awaitWriteFinish` makes
      // chokidar hold the event back until the file size is stable.
      // 100ms is comfortably above the longest gap we've measured
      // between save bursts from VSCode / typical export tools.
      stabilityThreshold: 100,
      pollInterval: 50,
    },
  });

  let pending: NodeJS.Timeout | null = null;
  const trigger = () => {
    if (pending) clearTimeout(pending);
    pending = setTimeout(() => {
      pending = null;
      dim('Change detected, rebuilding…');
      void runOnce(opts);
    }, WATCH_DEBOUNCE_MS);
  };

  watcher.on('add', trigger);
  watcher.on('change', trigger);
  watcher.on('unlink', trigger);

  // Graceful shutdown — without this Ctrl-C leaves chokidar's
  // file handles open until the process group dies.
  const shutdown = () => {
    void watcher.close().then(() => process.exit(0));
  };
  process.on('SIGINT', shutdown);
  process.on('SIGTERM', shutdown);
}
