// Audio pipeline.
//
// Reads every `.wav` / `.mp3` / `.flac` / `.m4a` under
// `<input>/audio/`, transcodes each one to Ogg Vorbis at a bitrate
// chosen by its top-level subdirectory (sfx → 96k, music → 128k,
// environment → 96k), and writes the result under
// `<output>/audio/` preserving the input directory structure.
// Identifiers are bubbled up to the type generator so consumer
// code can refer to sounds via the strictly-typed unions
// `SfxId | MusicId | EnvironmentId` (collectively `AudioId`).
//
// Why FFmpeg + libvorbis:
// Ogg Vorbis is the smallest of the broadly-supported web audio
// codecs at SFX-quality bitrates (~96kbps), and FFmpeg's
// `libvorbis` encoder is the de-facto reference. We bundle the
// FFmpeg binary via `@ffmpeg-installer/ffmpeg` so the pipeline
// runs on a fresh checkout without forcing every developer to
// install FFmpeg system-wide.
//
// Concurrency:
// Audio encoding is CPU-bound. Running every file in parallel via
// `Promise.all` would saturate the CPU and balloon RAM as multiple
// FFmpeg processes hold their decoded buffers simultaneously. We
// chunk into batches of `CONCURRENCY_LIMIT` instead — a small,
// fixed number that keeps memory bounded and progress logging
// readable.

import { extname, join, posix, relative, sep } from 'node:path';
import fse from 'fs-extra';
import ffmpeg from 'fluent-ffmpeg';
import { glob } from 'glob';
import { pathToIdentifier } from '../utils/identifier.js';
import { dim, error, info, success, warn } from '../utils/log.js';

/** Point fluent-ffmpeg at an ffmpeg binary, or report that there isn't one.
 *
 *  `@ffmpeg-installer/ffmpeg` is a 35 MB per-platform binary — the single
 *  largest thing forge could install, and useless to a game with no audio. It
 *  is an OPTIONAL peer dependency: pnpm does not install it, so this resolves
 *  it at the moment audio is actually being encoded rather than at import.
 *
 *  Three outcomes, in preference order:
 *    1. the bundled binary is installed → use it (the reproducible path);
 *    2. it isn't, but ffmpeg is on PATH → use that, and say so, since a
 *       developer with a system ffmpeg should not be made to download another;
 *    3. neither → the caller reports both ways to fix it.
 *
 *  Resolved ONCE per process and memoised — the probe spawns `ffmpeg -version`,
 *  and doing that per file would cost more than the encodes. */
let ffmpegSource: 'bundled' | 'path' | 'missing' | null = null;

async function resolveFfmpeg(): Promise<'bundled' | 'path' | 'missing'> {
  if (ffmpegSource !== null) return ffmpegSource;
  try {
    const installer = (await import('@ffmpeg-installer/ffmpeg')) as {
      default?: { path?: string };
      path?: string;
    };
    const binary = installer.default?.path ?? installer.path;
    if (typeof binary === 'string' && binary.length > 0) {
      ffmpeg.setFfmpegPath(binary);
      ffmpegSource = 'bundled';
      return ffmpegSource;
    }
  } catch {
    // Not installed — fall through to the PATH probe.
  }
  ffmpegSource = (await ffmpegOnPath()) ? 'path' : 'missing';
  return ffmpegSource;
}

/** Is a usable `ffmpeg` on PATH? fluent-ffmpeg defaults to invoking `ffmpeg`
 *  when no explicit path is set, so this asks IT rather than guessing. */
function ffmpegOnPath(): Promise<boolean> {
  return new Promise((resolve) => {
    ffmpeg.getAvailableFormats((err) => resolve(!err));
  });
}

/** What to tell an author whose game has audio but no encoder. Both fixes,
 *  because either one genuinely works. */
const NO_FFMPEG_MESSAGE =
  'Audio: found files to encode, but no ffmpeg is available.\n' +
  '  Install the bundled binary:  pnpm add -D @ffmpeg-installer/ffmpeg\n' +
  '  …or install ffmpeg system-wide and make sure it is on your PATH.';

const SUPPORTED_EXTENSIONS = new Set(['.wav', '.mp3', '.flac', '.m4a']);

/** How many ffmpeg processes may run at once. 2 keeps a typical
 *  laptop responsive while still hiding I/O waits behind the next
 *  encode. Bump to 4+ on big-iron CI; drop to 1 to debug encoder
 *  output deterministically. */
const CONCURRENCY_LIMIT = 2;

/** Per-bucket encoder quality. Vorbis was designed around
 *  quality-based VBR (`-q:a N`, 0..10) — its CBR mode is finicky
 *  and rejects (rate, channels, bitrate) tuples like 22050Hz mono
 *  @ 96kbps that work fine in VBR. We encode in VBR and document
 *  the approximate average bitrate so the bucket policy reads
 *  predictably to humans tuning it.
 *
 *  Quality → ~avg bitrate (per Vorbis spec table):
 *    q=2  → ~96 kbps  (acceptable SFX / ambience)
 *    q=4  → ~128 kbps (music — the "sweet spot" for streaming)
 *
 *  Files in unknown top-level subdirs trigger a yellow warning
 *  so devs notice mis-filed assets before they ship. */
const BUCKET_CONFIG: Record<
  AudioBucket,
  { quality: number; nominalBitrate: string }
> = {
  sfx: { quality: 2, nominalBitrate: '96k' },
  music: { quality: 4, nominalBitrate: '128k' },
  environment: { quality: 2, nominalBitrate: '96k' },
};

const BUCKET_NAMES = ['sfx', 'music', 'environment'] as const;
export type AudioBucket = (typeof BUCKET_NAMES)[number];

/** A single processed audio file's contribution to type generation. */
export interface AudioAsset {
  /** TS-safe identifier — e.g. `laser_shoot`. Derived from the
   *  file's path RELATIVE to its bucket root, so a nested
   *  `music/boss/intro.wav` becomes `boss_intro`. */
  identifier: string;
  /** Public path under the app's `public/` dir, with a leading
   *  slash and POSIX separators — e.g. `/audio/sfx/laser_shoot.ogg`. */
  publicPath: string;
}

/** The categorized return shape. Buckets are always present (even
 *  when empty) so the type generator can emit `never`-valued
 *  unions without a presence check. */
export type AudioAssetMap = Record<AudioBucket, AudioAsset[]>;

export interface RunAudioPipelineArgs {
  inputDir: string;
  outputDir: string;
}

export async function runAudioPipeline(
  args: RunAudioPipelineArgs,
): Promise<AudioAssetMap> {
  const audioInputRoot = join(args.inputDir, 'audio');
  const audioOutputRoot = join(args.outputDir, 'audio');
  const empty: AudioAssetMap = { sfx: [], music: [], environment: [] };

  if (!(await fse.pathExists(audioInputRoot))) {
    dim('Audio: skipped (no audio directory under input)');
    return empty;
  }

  const allFiles = await glob('**/*', {
    cwd: audioInputRoot,
    nodir: true,
    posix: true,
  });

  // Bucket each file by its top-level subdirectory. Files that
  // don't sit under a known bucket get a single yellow warning
  // and are skipped — better to surface mis-filed assets early
  // than silently dump them into a default bucket.
  const supported: Array<{ relPath: string; bucket: AudioBucket }> = [];
  for (const file of allFiles) {
    if (!SUPPORTED_EXTENSIONS.has(extname(file).toLowerCase())) {
      warn(
        `Audio: unsupported file type, skipping ${posix.join('audio', file)}`,
      );
      continue;
    }
    const bucket = bucketForPath(file);
    if (!bucket) {
      warn(
        `Audio: ${posix.join('audio', file)} is not under a known bucket (sfx/music/environment); skipping.`,
      );
      continue;
    }
    supported.push({ relPath: file, bucket });
  }

  if (supported.length === 0) {
    dim('Audio: no encodable files found');
    await fse.emptyDir(audioOutputRoot);
    return empty;
  }

  // Resolve the encoder only now — with files in hand. A game with no audio
  // never probes for ffmpeg, and never needs it installed.
  const source = await resolveFfmpeg();
  if (source === 'missing') {
    error(NO_FFMPEG_MESSAGE);
    throw new Error('Audio pipeline: no ffmpeg available');
  }
  if (source === 'path') {
    dim('Audio: using ffmpeg from PATH (@ffmpeg-installer/ffmpeg not installed)');
  }

  await fse.emptyDir(audioOutputRoot);
  info(
    `Audio: encoding ${supported.length} file${supported.length === 1 ? '' : 's'} (concurrency ${CONCURRENCY_LIMIT})…`,
  );

  // Track byte counts so we can report compression savings — a
  // satisfying signal that the pipeline is actually doing work.
  let inputBytes = 0;
  let outputBytes = 0;

  // Run with a fixed-concurrency batch loop. A library like
  // `p-limit` would do the same job; we avoid it to keep the dep
  // count low (this pipeline is the first place audio encoding
  // shows up — no elsewhere we'd reuse the limiter).
  const result: AudioAssetMap = { sfx: [], music: [], environment: [] };
  for (let i = 0; i < supported.length; i += CONCURRENCY_LIMIT) {
    const batch = supported.slice(i, i + CONCURRENCY_LIMIT);
    const batchResults = await Promise.all(
      batch.map((entry) =>
        encodeOne(entry, audioInputRoot, audioOutputRoot).catch((cause) => {
          warn(
            `Audio Encode Failed for ${posix.join('audio', entry.relPath)}: ${cause instanceof Error ? cause.message : String(cause)}`,
          );
          return null;
        }),
      ),
    );
    for (const r of batchResults) {
      if (!r) continue;
      result[r.asset.bucket].push({
        identifier: r.asset.identifier,
        publicPath: r.asset.publicPath,
      });
      inputBytes += r.bytesIn;
      outputBytes += r.bytesOut;
    }
  }

  // Stable, sorted output → stable generated TS → minimal VCS diffs.
  for (const bucket of BUCKET_NAMES) {
    result[bucket].sort((a, b) => a.identifier.localeCompare(b.identifier));
  }

  const totalProcessed =
    result.sfx.length + result.music.length + result.environment.length;
  const savedMB = ((inputBytes - outputBytes) / (1024 * 1024)).toFixed(1);
  success(
    `Audio: compressed ${totalProcessed} file${totalProcessed === 1 ? '' : 's'} to .ogg (saved ${savedMB}MB) → ${relative(process.cwd(), audioOutputRoot)}`,
  );

  return result;
}

interface EncodeResult {
  asset: AudioAsset & { bucket: AudioBucket };
  bytesIn: number;
  bytesOut: number;
}

/** Encode a single file. Returns the processed asset metadata
 *  + before/after sizes. Errors propagate to the caller, which
 *  catches and warns (rather than aborting the whole batch). */
async function encodeOne(
  entry: { relPath: string; bucket: AudioBucket },
  audioInputRoot: string,
  audioOutputRoot: string,
): Promise<EncodeResult> {
  const absInput = join(audioInputRoot, entry.relPath);
  // Output path: same relative tree under <output>/audio/, but
  // with the extension swapped to `.ogg`.
  const relOgg = swapExtension(entry.relPath, '.ogg');
  const absOutput = join(audioOutputRoot, relOgg);
  await fse.ensureDir(join(absOutput, '..'));

  // Identifier: the path RELATIVE to the bucket root, without
  // extension, sanitized to a valid TS identifier. Strips the
  // leading bucket folder so `sfx/laser.wav` → `laser`, and
  // `music/boss/intro.wav` → `boss_intro`.
  const relWithinBucket = entry.relPath.slice(entry.bucket.length + 1);
  const identifier = pathToIdentifier(relWithinBucket);

  await runFfmpeg(absInput, absOutput, BUCKET_CONFIG[entry.bucket].quality);

  const [statIn, statOut] = await Promise.all([
    fse.stat(absInput),
    fse.stat(absOutput),
  ]);

  return {
    asset: {
      bucket: entry.bucket,
      identifier,
      publicPath:
        '/' +
        posix.join('audio', relOgg.split(sep).join(posix.sep)),
    },
    bytesIn: statIn.size,
    bytesOut: statOut.size,
  };
}

/** Wrap fluent-ffmpeg's event-driven API as a Promise. The
 *  ffmpeg() builder is one-shot — chaining stops once `.save()` is
 *  called, so we instantiate fresh per file.
 *
 *  Why `outputOption('-q:a')` instead of `audioBitrate()`:
 *  fluent-ffmpeg's `.audioBitrate()` translates to `-b:a`, which
 *  forces CBR. Vorbis CBR rejects low-rate / mono inputs at
 *  conventional SFX bitrates (e.g. 22050Hz mono @ 96kbps). We use
 *  Vorbis's native VBR knob `-q:a N` instead — works on any input
 *  shape, and `BUCKET_CONFIG` exposes the nominal bitrate so the
 *  policy still reads in kbps. */
function runFfmpeg(
  input: string,
  output: string,
  quality: number,
): Promise<void> {
  return new Promise((resolve, reject) => {
    ffmpeg(input)
      .audioCodec('libvorbis')
      .outputOption('-q:a', String(quality))
      .toFormat('ogg')
      .on('end', () => resolve())
      .on('error', (err: Error) => reject(err))
      .save(output);
  });
}

/** Decide which bucket a relative-to-`<input>/audio/` path belongs
 *  to. Looks at the first POSIX-separated segment only — paths
 *  without a leading recognized bucket return null. */
function bucketForPath(relPath: string): AudioBucket | null {
  const slash = relPath.indexOf('/');
  if (slash === -1) return null;
  const head = relPath.slice(0, slash);
  return (BUCKET_NAMES as ReadonlyArray<string>).includes(head)
    ? (head as AudioBucket)
    : null;
}

function swapExtension(p: string, newExt: string): string {
  const ext = extname(p);
  return p.slice(0, p.length - ext.length) + newExt;
}
