// UI image pipeline.
//
// Takes every image under `<input>/images/ui/**` and emits a webp
// equivalent under `<output>/ui/**`, preserving the relative
// directory layout. The webp output is the universal modern format
// for static UI textures: ~25% smaller than equivalent png at
// similar visual quality, and decoded by every browser we target.
//
// Each input file produces one entry in the returned array — the
// derived id (used by the type generator) and the public path
// (relative to the app's `public/` dir, ready to drop into an
// <img src> or <Image src>).

import { extname, join, posix, relative, sep } from 'node:path';
import fse from 'fs-extra';
import { glob } from 'glob';
import sharp from 'sharp';
import { pathToIdentifier } from '../utils/identifier.js';
import { dim, info, success, warn } from '../utils/log.js';

/** Extensions handled by the UI pipeline. Anything else falls
 *  through to the unsupported-file warning in `cli.ts`. */
const SUPPORTED_EXTENSIONS = new Set(['.png', '.jpg', '.jpeg']);

/** Quality knob for sharp's webp encoder. 80 is the empirical
 *  sweet spot for UI textures: visible artefacts only on close
 *  inspection, file sizes ~30% of the source PNG. */
const WEBP_QUALITY = 80;

export interface UiAsset {
  /** TS-safe identifier — e.g. `backgrounds_menu`. */
  id: string;
  /** Path under the app's `public/` dir, with a leading slash and
   *  POSIX separators — e.g. `/ui/backgrounds/menu.webp`. Suitable
   *  for direct insertion into `<img src>` or as a Next.js Image
   *  source. */
  publicPath: string;
}

export interface RunUiPipelineArgs {
  inputDir: string;
  outputDir: string;
}

/**
 * Find UI source images, transcode each to webp, return the asset
 * list. `<output>/ui/` is wiped before writing so deletions in
 * `<input>` don't leave orphan webps behind.
 */
export async function runUiPipeline(args: RunUiPipelineArgs): Promise<UiAsset[]> {
  const uiInputRoot = join(args.inputDir, 'images', 'ui');
  const uiOutputRoot = join(args.outputDir, 'ui');

  if (!(await fse.pathExists(uiInputRoot))) {
    dim(`UI: skipped (no ${posix.normalize('images/ui')} directory under input)`);
    return [];
  }

  // Match all candidate files, then partition into supported / not
  // so we can warn (not crash) on the unsupported ones.
  const allFiles = await glob('**/*', {
    cwd: uiInputRoot,
    nodir: true,
    posix: true,
  });

  const supported: string[] = [];
  for (const file of allFiles) {
    if (SUPPORTED_EXTENSIONS.has(extname(file).toLowerCase())) {
      supported.push(file);
    } else {
      warn(`UI: unsupported file type, skipping ${posix.join('images/ui', file)}`);
    }
  }

  if (supported.length === 0) {
    dim('UI: no images to process');
    return [];
  }

  // Wipe output dir for a clean rebuild — the only way to
  // guarantee deleted source files don't linger as stale webps.
  await fse.emptyDir(uiOutputRoot);

  info(`UI: processing ${supported.length} image${supported.length === 1 ? '' : 's'}…`);

  const assets: UiAsset[] = [];
  for (const relPath of supported) {
    const absInput = join(uiInputRoot, relPath);
    const relWebp = swapExtension(relPath, '.webp');
    const absOutput = join(uiOutputRoot, relWebp);

    try {
      await fse.ensureDir(join(absOutput, '..'));
      await sharp(absInput).webp({ quality: WEBP_QUALITY }).toFile(absOutput);

      assets.push({
        id: pathToIdentifier(relPath),
        // Always emit POSIX separators in the public path so the
        // generated TS file is identical on macOS/Linux/Windows.
        publicPath:
          '/' +
          posix.join('ui', relWebp.split(sep).join(posix.sep)),
      });
    } catch (cause) {
      warn(
        `UI: failed to process ${posix.join('images/ui', relPath)} — ${
          cause instanceof Error ? cause.message : String(cause)
        }`,
      );
    }
  }

  // Stable order in the returned array → stable order in the
  // generated TS union → minimal diffs in version control.
  assets.sort((a, b) => a.id.localeCompare(b.id));

  success(`UI: emitted ${assets.length} webp file${assets.length === 1 ? '' : 's'} → ${relative(process.cwd(), uiOutputRoot)}`);
  return assets;
}

function swapExtension(relPath: string, newExt: string): string {
  const ext = extname(relPath);
  return relPath.slice(0, relPath.length - ext.length) + newExt;
}
