// The registry-emitter seam — language-open.
//
// A `RegistryEmitter` renders the language-neutral `AssetManifest` into a
// per-language binding. There are exactly two kinds, and NEITHER teaches
// forge a language's syntax:
//
//   - the BUILT-IN `tsRegistryEmitter` — the reference, writes the
//     TypeScript `lib/generated/assets.ts` byte-for-byte as always;
//   - the generic `createCommandRegistryEmitter` — wraps an EXTERNAL emitter
//     command the game's `.atelier/target.json` supplies, invoked via the
//     emitter ABI (`<command> --manifest <path> --out <path>`). The emitter
//     is a user- or community-authored package written in any language.
//
// forge ships ONE built-in (typescript). Any other language is an external
// emitter command (Tier 1) or a game loading `asset-manifest.json` directly
// (Tier 0). This mirrors @unsupervised/registry-cloud's ecosystem-neutral split. See
// docs/specs/language-agnostic-targets.md.

import { spawn } from 'node:child_process';
import { resolve } from 'node:path';
import fse from 'fs-extra';
import type { AssetManifest, RegistryEmitterSpec } from '@unsupervised/schemas';
import { renderTsRegistry } from './typeGenerator.js';

/** What an emitter is handed for one run. */
export interface RegistryEmitContext {
  manifest: AssetManifest;
  /** Absolute path of the on-disk `asset-manifest.json` (external emitters
   *  read this). May be absent for callers that don't persist the manifest —
   *  external emitters then error, the built-in TS emitter does not. */
  manifestPath?: string;
  /** Where this emitter writes its binding. */
  outputPath: string;
}

export interface RegistryEmitter {
  readonly id: string;
  emit(ctx: RegistryEmitContext): Promise<void>;
}

/** The built-in reference emitter. Renders the TS registry from the manifest
 *  already in memory. */
export const tsRegistryEmitter: RegistryEmitter = {
  id: 'typescript',
  async emit(ctx) {
    await fse.outputFile(ctx.outputPath, renderTsRegistry(ctx.manifest));
  },
};

/** The only built-in emitter. Everything else is external. */
const BUILTIN_REGISTRY_EMITTERS: Record<string, RegistryEmitter> = {
  typescript: tsRegistryEmitter,
};

/**
 * Build an emitter that shells out to an external command (the emitter ABI).
 * forge writes the neutral manifest, then runs
 * `<command> --manifest <manifestPath> --out <outputPath>`; the command reads
 * the JSON and writes the binding in its own language. A non-zero exit — or a
 * zero exit that produced no file — fails the build.
 */
export function createCommandRegistryEmitter(spec: {
  id: string;
  command: string;
}): RegistryEmitter {
  return {
    id: spec.id,
    async emit(ctx) {
      if (ctx.manifestPath === undefined) {
        throw new Error(
          `External registry emitter '${spec.id}' needs the manifest on disk, ` +
            `but forge wrote none (no --manifest path). This is a forge bug if ` +
            `it happens during a normal build.`,
        );
      }
      const code = await runEmitterCommand(
        spec.command,
        ctx.manifestPath,
        ctx.outputPath,
      );
      if (code !== 0) {
        throw new Error(
          `Registry emitter '${spec.id}' failed (exit ${code}): ` +
            `\`${spec.command}\`. See its output above.`,
        );
      }
      if (!(await fse.pathExists(ctx.outputPath))) {
        throw new Error(
          `Registry emitter '${spec.id}' exited 0 but wrote no binding at ` +
            `${ctx.outputPath}. The emitter must write the file passed as --out.`,
        );
      }
    },
  };
}

/** A resolved emitter paired with the concrete file it writes. */
export interface ResolvedRegistryEmitter {
  emitter: RegistryEmitter;
  outputPath: string;
}

/**
 * Turn the descriptor's `registryEmitters` specs into runnable emitters.
 * Pure (no I/O) — throws early on an unknown built-in so a bad descriptor
 * fails before forge writes anything. A string names a built-in (writing to
 * `defaultOutputPath`); an object is an external emitter (writing to its own
 * `output`, resolved against `gameRoot`).
 */
export function resolveRegistryEmitters(
  specs: RegistryEmitterSpec[],
  opts: { defaultOutputPath: string; gameRoot: string },
): ResolvedRegistryEmitter[] {
  return specs.map((spec) => {
    if (typeof spec === 'string') {
      const emitter = BUILTIN_REGISTRY_EMITTERS[spec];
      if (emitter === undefined) {
        throw new Error(
          `No built-in registry emitter '${spec}'. Only 'typescript' is ` +
            `built in; supply any other language as an external emitter ` +
            `{ id, command, output } in .atelier/target.json's registryEmitters. ` +
            `See docs/specs/language-agnostic-targets.md.`,
        );
      }
      return { emitter, outputPath: opts.defaultOutputPath };
    }
    return {
      emitter: createCommandRegistryEmitter(spec),
      outputPath: resolve(opts.gameRoot, spec.output),
    };
  });
}

/** Spawn an external emitter command through the shell (the command string is
 *  author-controlled build config, same trust as an npm script), appending
 *  the ABI's `--manifest` / `--out` arguments. */
function runEmitterCommand(
  command: string,
  manifestPath: string,
  outputPath: string,
): Promise<number> {
  const full = `${command} --manifest ${quote(manifestPath)} --out ${quote(outputPath)}`;
  return new Promise((resolvePromise) => {
    const child = spawn(full, { stdio: 'inherit', shell: true });
    child.on('exit', (code) => resolvePromise(code ?? 0));
    child.on('error', () => resolvePromise(1));
  });
}

/** Double-quote a path for the shell, escaping embedded quotes. */
function quote(value: string): string {
  return `"${value.replace(/"/g, '\\"')}"`;
}
