// Read a game's `.atelier/target.json` and resolve it to a full
// `GameTarget`. forge uses the resolved `registryEmitters` to choose which
// language bindings to render from the manifest. An absent descriptor ⇒ the
// TypeScript/web default, so today's games are unchanged.
//
// The fs read lives here; the parsing + defaulting is @unsupervised/schemas'
// `resolveGameTarget` (the canonical contract, shared with @unsupervised/packager).

import { join } from 'node:path';
import fse from 'fs-extra';
import { type GameTarget, resolveGameTarget } from '@unsupervised/schemas';

/** Path of a game's target descriptor, relative to its root. */
export function targetDescriptorPath(rootDir: string): string {
  return join(rootDir, '.atelier', 'target.json');
}

/**
 * Resolve the `GameTarget` for a game root. Missing descriptor ⇒ the
 * default (TS/web). A present-but-malformed descriptor throws — a broken
 * target is a build-time bug, not a silent fallback.
 */
export async function resolveTargetForRoot(
  rootDir: string,
): Promise<GameTarget> {
  const path = targetDescriptorPath(rootDir);
  if (!(await fse.pathExists(path))) {
    return resolveGameTarget(null);
  }
  const raw: unknown = await fse.readJson(path);
  return resolveGameTarget(raw);
}
