// NavMesh tile pipeline.
//
// Reads `<input>/navmeshes/<world-id>/world.json` per world,
// bakes per-tile binary navmesh data via recast-navigation,
// and emits a typed manifest the host app's
// `lib/generated/assets.ts` exposes via
// `NAVMESH_TILE_MANIFESTS[<worldId>]`.
//
// Why a SUBPROCESS for the actual bake:
// recast-navigation's WASM module aborts when initialized
// alongside the other heavy modules (Sharp, Draco, ffmpeg)
// in the same Node process — proven by experiment, the
// same `init()` call that succeeds in plain `node -e ...`
// aborts inside the bundled forge CLI even with 4GB heap.
// Spawning a child process for the bake gives recast a
// clean memory space; we then read the emitted
// `manifest.json` files back from disk for type generation.
// Per-world bake is fast (10–100ms typical) so the
// subprocess overhead is negligible.
//
// Why JSON-shaped sources, not GLB:
// recast bakes from a triangle buffer (positions + indices).
// GLB extraction would pull `gltf-transform` into the bake
// path. The navmesh source is small (a few hundred AABBs
// for a typical world) so JSON is the right authoring
// format. GLB-source baking is in OUT_OF_SCOPE for a future
// game whose hand-modeled streaming geometry justifies the
// round-trip.
//
// Why per-tile binaries (not one big serialized NavMesh):
// runtime streaming wants to fetch only the tiles in view.
// A single bundle would force the browser to download the
// whole world up front, defeating the streaming feature.

import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import fse from 'fs-extra';
import { glob } from 'glob';
import {
  type NavMeshTileManifest,
  NavMeshTileManifestSchema,
  type TileCacheManifest,
  TileCacheManifestSchema,
} from '@unsupervised/schemas';
import { dim, info, success, warn } from '../utils/log.js';

/** What the pipeline returns to the type generator: an
 *  identifier (the world directory name) plus the complete
 *  manifest, ready to emit as a TS const literal. */
export interface NavMeshAsset {
  identifier: string;
  manifest: NavMeshTileManifest;
}

/** TileCache-format manifest asset. Forge-baked as a single
 *  bundle binary per world; the runtime imports the bundle
 *  via `importTileCache` and supports runtime obstacle
 *  add / remove. Emitted into a separate
 *  `TILECACHE_MANIFESTS` const literal so apps can
 *  discriminate on the manifest shape at the type level. */
export interface TileCacheAsset {
  identifier: string;
  manifest: TileCacheManifest;
}

export interface NavMeshPipelineResult {
  /** Solo / streaming manifests (per-tile binaries). */
  navMesh: NavMeshAsset[];
  /** TileCache manifests (single-bundle, runtime-modifiable). */
  tileCache: TileCacheAsset[];
}

export interface RunNavMeshPipelineArgs {
  inputDir: string;
  outputDir: string;
}

/** Path to the standalone bake script. The script lives in
 *  `packages/forge/scripts/`; this module lives in
 *  `packages/forge/src/pipelines/` at dev time and
 *  `packages/forge/dist/` after build. */
function resolveBakeScript(): string {
  const here = dirname(fileURLToPath(import.meta.url));
  // Prefer dist-relative (production); fall back to
  // src-relative (vitest / direct ts-node).
  const distRel = join(here, '..', 'scripts', 'bake-navmesh-standalone.mjs');
  const srcRel = join(here, '..', '..', 'scripts', 'bake-navmesh-standalone.mjs');
  return fse.existsSync(distRel) ? distRel : srcRel;
}

/** Bake every navmesh world under `<input>/navmeshes/`.
 *  Spawns a child Node process running the standalone bake
 *  script (see file header for rationale).
 *
 *  The subprocess inspects each `world.json`'s `format`
 *  field and routes to either the solo path (per-tile
 *  streaming binaries) or the tilecache path (single
 *  runtime-modifiable bundle). Both manifest types live
 *  under `<output>/navmesh/<world>/manifest.json`; this
 *  pipeline reads each back and routes it via
 *  `safeParse` against both schemas — tilecache first
 *  (more specific shape with `bundlePath`), then solo. */
export async function runNavMeshPipeline(
  args: RunNavMeshPipelineArgs,
): Promise<NavMeshPipelineResult> {
  const navMeshInputRoot = join(args.inputDir, 'navmeshes');
  const empty: NavMeshPipelineResult = { navMesh: [], tileCache: [] };

  if (!(await fse.pathExists(navMeshInputRoot))) {
    dim('NavMeshes: skipped (no navmeshes directory under input)');
    return empty;
  }

  // Discover candidate world dirs first so we can bail early
  // if there's nothing to bake.
  const worldFiles = await glob('*/world.json', {
    cwd: navMeshInputRoot,
    posix: true,
  });
  if (worldFiles.length === 0) {
    dim('NavMeshes: no `<input>/navmeshes/<world>/world.json` files found');
    return empty;
  }

  // Run the bake in a subprocess.
  const bakeScript = resolveBakeScript();
  if (!(await fse.pathExists(bakeScript))) {
    warn(
      `NavMeshes: bake script not found at ${bakeScript}; pipeline disabled`,
    );
    return empty;
  }
  const exitCode = await runBakeChild(
    bakeScript,
    args.inputDir,
    args.outputDir,
  );
  if (exitCode !== 0) {
    warn(`NavMeshes: bake child process exited with code ${exitCode}`);
    return empty;
  }

  // Walk the output dir for manifests the bake wrote.
  const navMeshOutputRoot = join(args.outputDir, 'navmesh');
  const manifestFiles = await glob('*/manifest.json', {
    cwd: navMeshOutputRoot,
    posix: true,
  });

  const navMeshAssets: NavMeshAsset[] = [];
  const tileCacheAssets: TileCacheAsset[] = [];
  for (const manifestRel of manifestFiles) {
    const worldId = manifestRel.split('/')[0];
    if (!worldId) continue;
    const manifestPath = join(navMeshOutputRoot, manifestRel);
    try {
      const raw = await fse.readJson(manifestPath);
      // TileCache manifests have a unique `bundlePath`
      // field. Try that schema first; on miss, fall back
      // to the solo / streaming schema.
      const tileCacheParsed = TileCacheManifestSchema.safeParse(raw);
      if (tileCacheParsed.success) {
        tileCacheAssets.push({
          identifier: worldId,
          manifest: tileCacheParsed.data,
        });
        continue;
      }
      const navMeshParsed = NavMeshTileManifestSchema.safeParse(raw);
      if (!navMeshParsed.success) {
        warn(
          `NavMeshes: '${worldId}/manifest.json' didn't match either schema:\n - TileCache: ${tileCacheParsed.error.toString()}\n - Solo: ${navMeshParsed.error.toString()}`,
        );
        continue;
      }
      navMeshAssets.push({
        identifier: worldId,
        manifest: navMeshParsed.data,
      });
    } catch (cause) {
      warn(
        `NavMeshes: failed to read '${worldId}/manifest.json' — ${cause instanceof Error ? cause.message : String(cause)}`,
      );
    }
  }

  navMeshAssets.sort((a, b) => a.identifier.localeCompare(b.identifier));
  tileCacheAssets.sort((a, b) => a.identifier.localeCompare(b.identifier));

  const totalTiles = navMeshAssets.reduce(
    (acc, a) => acc + a.manifest.tiles.length,
    0,
  );
  const totalTileCacheTiles = tileCacheAssets.reduce(
    (acc, a) => acc + a.manifest.tiles.length,
    0,
  );
  if (navMeshAssets.length > 0 || tileCacheAssets.length > 0) {
    info(
      `NavMeshes: collected ${navMeshAssets.length} solo manifest${navMeshAssets.length === 1 ? '' : 's'} (${totalTiles} tile${totalTiles === 1 ? '' : 's'}) + ${tileCacheAssets.length} tilecache manifest${tileCacheAssets.length === 1 ? '' : 's'} (${totalTileCacheTiles} cell${totalTileCacheTiles === 1 ? '' : 's'})`,
    );
  }
  success(
    `NavMeshes: baked ${navMeshAssets.length + tileCacheAssets.length} world${navMeshAssets.length + tileCacheAssets.length === 1 ? '' : 's'}`,
  );
  return { navMesh: navMeshAssets, tileCache: tileCacheAssets };
}

function runBakeChild(
  scriptPath: string,
  inputDir: string,
  outputDir: string,
): Promise<number> {
  return new Promise((resolve) => {
    const child = spawn(
      process.execPath,
      [scriptPath, inputDir, outputDir],
      { stdio: 'inherit' },
    );
    child.on('exit', (code) => {
      resolve(code ?? 0);
    });
    child.on('error', () => {
      resolve(1);
    });
  });
}
